        getline(cin, catchphrase);
        villagerData[name] = make_tuple(friendshipLevel, species, catchphrase);
        cout << name << " added.\n";
        cout << endl;
        break;
      }
      case 2: {
        // Deletes a villager
        if (it != villagerData.end()) {
          villagerData.erase(name);
          cout << endl;
        } else {
          cout << name << " not found.\n";
          cout << endl;
        }
        break;
      }
      case 3: {
        // Increases friendship level of a villager
