using namespace std;

double* CreateArray(int n) {
    return new double[n];
}

void AutoFillArray(double* arr, int n) {
    srand((unsigned)time(nullptr));
    for (int i = 0; i < n; i++) 
    {
        arr[i] = (rand() % 2001 - 1000) / 100.0;
    }
}

void PrintArray(const double* arr, int n) 
{
    cout << fixed << setprecision(2);
    for (int i = 0; i < n; i++)
        cout << setw(8) << arr[i];
    cout << endl;
}

double ProductOfPositive(const double* arr, int n, bool& found) 
{
    found = false;
    double product = 1.0;
    for (int i = 0; i < n; i++) {
        if (arr[i] > 0) {
            product *= arr[i];
            found = true;
        }
    }
    return product;
}

int IndexOfMin(const double* arr, int n) 
{
    int idx = 0;
    for (int i = 1; i < n; i++)
        if (arr[i] < arr[idx])
            idx = i;
    return idx;
}

double SumBeforeMin(const double* arr, int n, int idxMin) 
{
    double sum = 0;
    for (int i = 0; i < idxMin; i++)
        sum += arr[i];
    return sum;
}

void BubbleSort(double* arr, int size) 
{
    for (int i = 0; i < size - 1; i++)
        for (int j = 0; j < size - i - 1; j++)
            if (arr[j] > arr[j + 1])
                swap(arr[j], arr[j + 1]);
}

void SortEvenOddPositions(double* arr, int n)
{
    if (n <= 1) return;

    int evenCount = (n + 1) / 2; 
    int oddCount = n / 2; 

    double* even = new double[evenCount];
    double* odd = new double[oddCount];

    int e = 0, o = 0;

    for (int i = 0; i < n; i++) {
        if (i % 2 == 0) {
            if (e < evenCount) even[e++] = arr[i];
        }
        else {
            if (o < oddCount) odd[o++] = arr[i];
        }
    }

    BubbleSort(even, e);
    BubbleSort(odd, o);

    e = o = 0;
    for (int i = 0; i < n; i++) {
        if (i % 2 == 0 && e < evenCount) arr[i] = even[e++];
        else if (o < oddCount) arr[i] = odd[o++];
    }

    delete[] even;
    delete[] odd;
}

int main() 
{
    int n;
    cout << "Введіть кількість елементів масиву: ";
    cin >> n;

    if (n <= 0) 
    {
        cout << "Невірне значення n!" << endl;
        return 0;
    }

    double* arr = CreateArray(n);
    AutoFillArray(arr, n);

    cout << "\nПочатковий масив:" << endl;
    PrintArray(arr, n);

    bool found;
    double product = ProductOfPositive(arr, n, found);
    if (found)
        cout << "\nДобуток додатних елементів: " << product << endl;
    else
        cout << "\nУ масиві немає додатних елементів!" << endl;

    int idxMin = IndexOfMin(arr, n);
    cout << "Мінімальний елемент: " << arr[idxMin]
        << " (індекс " << idxMin << ")" << endl;

    double sum = SumBeforeMin(arr, n, idxMin);
    cout << "Сума елементів до мінімального: " << sum << endl;

    SortEvenOddPositions(arr, n);
    cout << "\nМасив після сортування парних і непарних позицій:" << endl;
    PrintArray(arr, n);

    delete[] arr;
    return 0;
}
