void Init(const std::string& logfileName) {
    std::lock_guard<std::mutex> lg(g_logMutex);
    if (g_logFile.is_open()) g_logFile.close();
    g_logFile.open(logfileName, std::ios::app);
}

static std::string timeStamp() {
    auto now = std::chrono::system_clock::now();
    std::time_t t = std::chrono::system_clock::to_time_t(now);
#ifdef _WIN32
    char buf[64]; ctime_s(buf, sizeof(buf), &t);
#else
    char buf[64]; std::strftime(buf, sizeof(buf), "%c", std::localtime(&t));
#endif
    std::string s(buf);
    if (!s.empty() && s.back() == '\n') s.pop_back();
    return s;
}

void Log(const std::string& msg) {
    std::lock_guard<std::mutex> lg(g_logMutex);
    std::string entry = "[" + timeStamp() + "] " + msg;
    std::cout << entry << std::endl;
    if (g_logFile.is_open()) g_logFile << entry << std::endl;
}

void LogFileDetails(const std::string& path) {
    std::error_code ec;
    if (!std::filesystem::exists(path, ec)) { Log("[FileInfo] does not exist: " + path); return; }
    auto sz = std::filesystem::file_size(path, ec);
    if (!ec) Log("[FileInfo] " + path + " size=" + std::to_string(sz));
    else Log("[FileInfo] size error: " + ec.message());
    auto lw = std::filesystem::last_write_time(path, ec);
    if (!ec) {
        auto dur = lw.time_since_epoch();
        auto secs = std::chrono::duration_cast<std::chrono::seconds>(dur).count();
        Log("[FileInfo] last_write_time ticks=" + std::to_string(secs));
    } else {
        Log("[FileInfo] last_write_time error: " + ec.message());
    }
}

