    char buf[2048];
    while (true) {
        size_t received = xMessageBufferReceive(jsonMsgBuffer, buf, sizeof(buf) - 1, 0);
        if (received == 0) break;
        buf[received] = '\0';
        jsonAccumulator.push_back(buf);
    }
}

