    readJsonBuffer();
    if (jsonAccumulator.empty()) return;

    printf("\n");
    printf("────────────────────────────────────────────────────────────────────────────────\n");
    printf("STRUCTURED LOGS (JSON)\n");
    printf("────────────────────────────────────────────────────────────────────────────────\n");
