/**
 * @brief Implementacja algorytmu Monotone Chain (Andrew's).
 *
* ZZnajduje najmniejszy (najmniej liczny) podzbiór takich punktów, które
*otaczają wszystkie inne punkty.
 * Złożoność obliczeniowa: O(n log n) z powodu sortowania.
 *
 * @note Ta funkcja celowo pracuje na kopii wektora wejściowego,
 * aby nie modyfikować oryginalnych danych.
 *
 * @param all_points Wektor wszystkich wczytanych punktów.
 * @return Wektor punktów tworzących otoczkę wypukłą.
 */
vector<Point> monotone_chain_algorithm(const vector<Point>& all_points)
{
    // przypadki brzegowe
    if (all_points.size() <= 3)
    {
        return all_points;
    }

    // tworzenie kopii roboczej i sortowanie
    vector<Point> sorted_points = all_points;
    sort(sorted_points.begin(), sorted_points.end());

    vector<Point> L; //dolna otoczka
    vector<Point> U; //górna otoczka

    // budowanie dolnej otoczki (L)
    for (auto sorted_point : sorted_points)
    {
        // dopóki ostatni segment skręca w prawo (lub jest prosty), usuwaj punkty
        while (L.size() >= 2 && cross_product(L[L.size() - 2], L.back(), sorted_point) <= 0)
        {
            L.pop_back();
        }

        L.push_back(sorted_point);
    }
    // budowanie górnej otoczki (U)
    for (int i = sorted_points.size() - 1; i >= 0; --i)
    {
        while (U.size() >= 2 && cross_product(U[U.size() - 2], U.back(), sorted_points[i]) <= 0)
        {
            U.pop_back();
        }

        U.push_back(sorted_points[i]);
    }
    L.pop_back();// usunięcie skrajnego prawego duplikatu
    U.pop_back();// usunięcie skrajnego lewego duplikatu
    L.insert(L.end(), U.begin(), U.end()); // łączenie, finalna otoczka
    return L;
}

/**
 * @brief Funkcja wypisująca wynik Zadania 1.
 *
 * Iteruje po wektorze otoczki i wypisuje każdy punkt na konsolę.
