QStringList CameraConfig::getCameraDescriptions()
{
    const auto cameras = QCameraInfo::availableCameras();
    QStringList descriptions;
    for (const auto& camInfo : cameras) {
        descriptions.append(camInfo.description());
    }
    return descriptions;
}

std::vector<CameraConfig> CameraConfig::getSupportedCameraConfigs(int cameraIndex)
{
    std::vector<CameraConfig> configs;
    QList<QCameraInfo> cameras = QCameraInfo::availableCameras();

    if (cameraIndex >= cameras.size()) return configs;

    const QCameraInfo cameraInfo = cameras[cameraIndex];
    spdlog::info("Camera name: {}", cameraInfo.description().toStdString());

    QCamera camera(cameraInfo);
    camera.start();

    // 现在查询支持的设置
    QList<QCameraViewfinderSettings> supportedSettings = camera.supportedViewfinderSettings();
    spdlog::info("Available viewfinder settings: {}", supportedSettings.size());

    for (const QCameraViewfinderSettings& settings : supportedSettings) {
        CameraConfig config;
        config.width = settings.resolution().width();
        config.height = settings.resolution().height();
        config.fps = settings.maximumFrameRate();
        config.pixelFormat = magic_enum::enum_name(settings.pixelFormat()).data();

        // 添加到列表
        configs.emplace_back(config);

        spdlog::info("Supported config: {}", static_cast<std::string>(config));
    }

    camera.stop(); // 查询完成，停止摄像头

    return configs;
}

CameraConfig CameraConfig::selectBestCameraConfig(const std::vector<CameraConfig>& configs)
{
    // 1. 如果没有配置，返回默认配置
    if (configs.empty()) {
        return { 640, 480, 30, "Unknown" };
    }

    // 2. 如果系统内存 >= 8GB 且 CPU 核心 >= 8，选择分辨率最大的配置（帧数高优先）
    const auto ramGB = sysinfo::getSystemRAM<sysinfo::GB>();
    const auto cpuCores = sysinfo::getCPUCoreCount();
    if (ramGB >= 8 && cpuCores >= 8) {
        const auto best = std::ranges::max_element(configs,
            [](const CameraConfig& a, const CameraConfig& b) {
                const int resA = a.width * a.height;
                const int resB = b.width * b.height;
                if (resA == resB) return a.fps < b.fps; // 分辨率相同，选择帧数高的
                return resA < resB;
            });
        return *best;
    }

    // 3. 优先选择 1920x1080，如果多个相同分辨率，选择帧数最高的
    std::vector<CameraConfig> fullHDConfigs;
    for (const auto& cfg : configs) {
        if (cfg.width == 1920 && cfg.height == 1080) {
            fullHDConfigs.push_back(cfg);
        }
    }
    if (!fullHDConfigs.empty()) {
        const auto best = std::ranges::max_element(fullHDConfigs,
            [](const CameraConfig& a, const CameraConfig& b) {
                return a.fps < b.fps;
            });
        return *best;
    }

    // 4. 尝试选择 640x480 帧数
    for (const auto& cfg : configs) {
        if (cfg.width == 640 && cfg.height == 480) {
            return cfg;
        }
    }

    // 5. 如果以上都不符合，返回支持的最小分辨率
    return configs.front();
}


#include <stdio.h>
#include <iostream>

using namespace std;

#define MAX 55
#define MAX_DEQ (MAX * MAX * 2)
#define OFFSET (MAX_DEQ/2)

int N, M;
int position[MAX];
int deq[MAX_DEQ*2];
int front, back;

void input()
{
    cin >> N >> M;
    for(int i = 0; i<M; i++) cin >> position[i];
    front = back = OFFSET;
    for(int i = 1; i<= N; i++) deq[back++]=i;
}

int getLeftCnt(int val)
{
    int ret = 0;
    for(int i = front; i<back; i++)
    {
        if(deq[i]==val) return ret;
        ret++;
    }
    return -1;
}

int getRightCnt(int val)
{
    int ret = 0;
    for(int i=back-1; i>=front; i--)
    {
        ret++;
        if(deq[i]==val) return ret;
    }
    return -1;
}

int main(void)
{
    freopen("input.txt","r",stdin);
    input();
    // cout << deq[back-1] << endl;

    int ans = 0;
    for(int i =0; i<M; i++)
    {
        if(deq[front]==position[i]) front++;
        else
        {
            int leftCnt = getLeftCnt(position[i]);
            int rightCnt = getRightCnt(position[i]);
            if(rightCnt>leftCnt)
            {
                for(int k=0; k<leftCnt; k++)
                {
                    deq[back++] = deq[front++];
                }
                front++;
                ans += leftCnt;
            }
            else
            {
                for(int k =0; k<rightCnt; k++)
                    deq[--front] = deq[--back];
                front++;
                ans += rightCnt;
            }
        }
    }
    cout << ans << endl;
    return 0;
}
#include "core/hooks/hooks.hpp"

struct renderable_info_t {
	entity_t *renderable;
	std::byte pad[18];
	uint16_t flags;
	uint16_t flags2;
};

constexpr auto g_max_coord = 16384.0f;
constexpr auto g_min_coord = -g_max_coord;
const auto g_mins = vec3_t(g_min_coord, g_min_coord, g_min_coord);
const auto g_maxs = vec3_t(g_max_coord, g_max_coord, g_max_coord);

int __fastcall hooks::list_leaves_in_box::hook(void *ecx, void *edx, const vec3_t *mins, const vec3_t *maxs, uint16_t *list, int listmax) {
	static auto ret_addr = utilities::pattern_scan("client.dll", "56 52 FF 50 18") + 5;
	using fn_t = entity_t *(__thiscall *)(void *);

	if (_ReturnAddress() == ret_addr) {
		auto frame_addr  = reinterpret_cast<uint8_t *>(_AddressOfReturnAddress());
		auto info        = *reinterpret_cast<renderable_info_t **>(frame_addr + 0x14);
		auto unknown     = (**(fn_t **)info->renderable)(info->renderable);

		if (info != nullptr && unknown != nullptr) {
			auto entity = (*(fn_t **)unknown)[7](unknown);

			if(entity != nullptr && entity->is_player()) {
				info->flags  &= ~0x100;
				info->flags2 |=  0x040;

				return original(ecx, &g_mins, &g_maxs, list, listmax);
			}
		}
	}

	return original(ecx, mins, maxs, list, listmax);
}
