const char* ssid = "Wokwi-GUEST";
const char* password = "";

// Chân GPIO
const int buzzerPin = 25;
const int servoPin = 26;

// Cấu hình servo
Servo myServo;

// Chuông cửa
int melody[] = {659, 523};  // Ding-Dong
int noteDuration = 300;
int pauseBetweenNotes = 100;

WebServer server(80);

// Hàm phát chuông cửa
void playDoorbell() {
  // Tạo âm thanh bằng cách bit-banging
  for (int i = 0; i < 2; i++) { // Lặp lại cho 2 nốt Ding-Dong
    int freq = melody[i];
    int period = 1000000 / freq; // Chu kỳ tính bằng micro giây
    int cycles = (noteDuration * 1000) / period; // Số chu kỳ trong noteDuration

    for (int j = 0; j < cycles; j++) {
      digitalWrite(buzzerPin, HIGH);
      delayMicroseconds(period / 2);
      digitalWrite(buzzerPin, LOW);
      delayMicroseconds(period / 2);
    }
    delay(pauseBetweenNotes);
  }
}

// Trang chính
void handleRoot() {
  String responseMessage = "Gửi GET tới /servo?angle=X để điều khiển servo hoặc /doorbell để rung chuông.";
  server.send(200, "text/html; charset=UTF-8", "<html><body><h1>ESP32 Control</h1><p>" + responseMessage + "</p></body></html>");
}

// Xử lý điều khiển servo
void handleServo() {
  String angleStr = server.arg("angle");
  String responseMessage;

  if (angleStr != "") {
    int angle = angleStr.toInt();
    Serial.print("Received servo angle: ");
    Serial.println(angle);
    if (angle >= 0 && angle <= 180) {
      myServo.write(angle);
      responseMessage = "Servo đã được đặt ở " + String(angle) + " độ.";
    } else {
      responseMessage = "Góc không hợp lệ. Vui lòng cung cấp góc từ 0 đến 180.";
    }
  } else {
    responseMessage = "Không có giá trị angle.";
  }

  server.send(200, "text/html; charset=UTF-8", "<html><body><h1>ESP32 Servo Control</h1><p>" + responseMessage + "</p></body></html>");
}

// Xử lý chuông cửa qua HTTP
void handleDoorbell() {
  playDoorbell();
  server.send(200, "text/html; charset=UTF-8", "<html><body><h1>ESP32 Doorbell</h1><p>Chuông cửa đã rung!</p></body></html>");
}

void setup() {
  Serial.begin(115200);

  pinMode(buzzerPin, OUTPUT);
  myServo.attach(servoPin);
  myServo.write(0);

  // Kết nối WiFi
  WiFi.begin(ssid, password);
  Serial.print("Connecting to WiFi");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println("\nConnected! IP address: " + WiFi.localIP().toString());

  // Thiết lập HTTP server
  server.on("/", handleRoot);
  server.on("/servo", handleServo);
  server.on("/doorbell", handleDoorbell);

  server.begin();
