/**
 * @file task7.cpp
 * @brief Implements functions to check the validity (tautology) of a Conjunctive Normal Form (CNF) formula.
 *
 * A CNF formula is a tautology if and only if every single clause contains a pair of complementary
 * literals (e.g., 'P' and '~P', or '1' and '-1').
 *
 * @page task7_page Task 7: Check CNF Validity
 * @ingroup task7_page
 * @details This module performs a structural check on CNF clauses to determine if the formula is a tautology.
 * Two functions are provided for integer-based CNF (from file) and string-based CNF (from conversion).
 * @subpage task8_page
 */

#include <bits/stdc++.h>
using namespace std;

// --- Task 2 Structures (Required for Context) ---
/**
 * @brief Structure representing a node in the general propositional logic parse tree (char-based).
 * @ingroup task2_page
 */
struct node
{
    char data;
    node* left;
    node* right;

    node(char val)
    {
        data = val;
        left = NULL;
        right = NULL;
    }
};

/**
 * @brief Structure representing a node in the CNF-specific parse tree (string-based).
 * @ingroup task2_page
 */
struct nodeCNF
{
    string data;
    nodeCNF* left;
    nodeCNF* right;

    nodeCNF(string val)
    {
        data = val;
        left = NULL;
        right = NULL;
    }
};

// --- Task 8 Functions: Memory Cleanup ---

/**
 * @brief Recursively deallocates all nodes in a general propositional logic parse tree.
 * @ingroup task8_page
 * @param root A pointer to the root of the tree to delete.
 */
void deleteTree(node* root)
{
    if (root == NULL) return;
    deleteTree(root->left);
    deleteTree(root->right);
    delete root;
}

/**
 * @brief Recursively deallocates all nodes in a CNF parse tree.
 * @ingroup task8_page
 * @param root A pointer to the root of the CNF tree to delete.
 */
void deleteCNFTree(nodeCNF* root)
{
    if (root == NULL) return;
    deleteCNFTree(root->left);
    deleteCNFTree(root->right);
    delete root;
}


// --- Task 7 Functions ---

/**
 * @brief Checks the validity of a CNF formula given as a vector of integer clauses (from a file).
 * @ingroup task7_page
 * @param v A vector of vectors of integers representing the CNF clauses.
 * @return True if the entire CNF formula is valid (all clauses are tautologies), false otherwise.
 * * @complexity
 * Time: O(C * L_max), where C is the number of clauses and L_max is the max literals in a clause.
 * Space: O(L_max), for the temporary unordered_set.
 */
bool checkvalidity_cnffile(vector<vector<int>> &v)
{
    int validCount = 0, invalidCount = 0;

    for (const auto& row : v)
    {
        unordered_set<int> s(row.begin(), row.end());
        bool isTautology = false;

        // Check for complementary literals: j and -j in the same clause
        for (int lit : row)
        {
            if (s.count(-lit))
            {
                isTautology = true;
                break;
            }
        }

        if (isTautology)
            validCount++;
        else
            invalidCount++;
    }

    cout << "Valid clauses (tautologies): " << validCount << endl;
    cout << "Invalid clauses (not tautologies): " << invalidCount << endl;

    // A CNF formula is a tautology iff every clause is a tautology.
    return invalidCount == 0;
}

/**
 * @brief Checks the validity of a CNF formula given as a vector of string literals (from conversion).
 * @ingroup task7_page
 * @param v A vector of vectors of strings representing the CNF clauses.
 * @return True if the entire CNF formula is valid, false otherwise.
 * * @complexity
 * Time: O(C * L_max * K), where C is the number of clauses, L_max is the max literals per clause, and K is the max length of a literal string.
 * Space: O(L_max * K), for the temporary unordered_set.
 */
bool checkvalidity_string(vector<vector<string>> &v)
{
    int validCount = 0, invalidCount = 0;

    for (const auto& row : v)
    {
        unordered_set<string> s(row.begin(), row.end());
        bool isTautology = false;

        // Check for complementary literals
        for (const string& lit : row)
        {
            // Determine the negation of the literal
            string neg;
            if (!lit.empty() && lit[0] == '~')
            {
                neg = lit.substr(1); // Negation of ~P is P
            } else {
                neg = "~" + lit; // Negation of P is ~P
            }

            if (s.count(neg))
            {
                isTautology = true;
                break;
            }
        }

        if (isTautology)
            validCount++;
        else
            invalidCount++;
    }

    cout << "Valid clauses (tautologies): " << validCount << endl;
    cout << "Invalid clauses (not tautologies): " << invalidCount << endl;

    return invalidCount == 0;
}


