using namespace std;

int main() {
    int nb, np, cap;
    cout << "Enter number of buses: ";
    cin >> nb;
    int buses[100];
    cout << "Enter bus times: ";
    for (int i = 0; i < nb; i++) cin >> buses[i];

    cout << "Enter number of passengers: ";
    cin >> np;
    int pas[100];
    cout << "Enter passenger times: ";
    for (int i = 0; i < np; i++) cin >> pas[i];

    cout << "Enter capacity of each bus: ";
    cin >> cap;

    // sort buses
    for (int i = 0; i < nb - 1; i++) {
        for (int j = i + 1; j < nb; j++) {
            if (buses[i] > buses[j]) {
                int t = buses[i];
                buses[i] = buses[j];
                buses[j] = t;
            }
        }
    }

    // sort passengers
    for (int i = 0; i < np - 1; i++) {
        for (int j = i + 1; j < np; j++) {
            if (pas[i] > pas[j]) {
                int t = pas[i];
                pas[i] = pas[j];
                pas[j] = t;
            }
        }
    }

    int j = 0, last = -1, cnt = 0, t = 0;

    for (int i = 0; i < nb; i++) {
        cnt = 0;
        while (j < np && pas[j] <= buses[i] && cnt < cap) {
            last = pas[j];
            j++;
            cnt++;
        }
        if (i == nb - 1) {
            if (cnt < cap) t = buses[i];
            else t = last - 1;
        }
    }

    bool same = true;
    while (same) {
        same = false;
        for (int i = 0; i < np; i++) {
            if (pas[i] == t) {
                t--;
                same = true;
                break;
            }
        }
    }

    cout << "The latest time you can arrive is: " << t;
    return 0;
}
