auto to_lower_string(std::string string) -> std::string {
    // NOLINTNEXTLINE(boost-use-ranges,modernize-use-ranges): prefer simple loop instead of std::ranges::copy(std::ranges::views::transform(..., ...), ...)
    std::transform(string.begin(), string.end(), string.begin(), [](const char character) {
        return std::tolower(character);
    });
    return string;
}

auto remove_string_suffix(std::string_view string, std::string_view suffix) -> std::string_view {
    if (string.ends_with(suffix)) {
        string.remove_suffix(suffix.length());
    }
    return string;
}

auto get_field_name(const nvmlGpmMetric_t & gpm_metric) -> std::string {
    std::string field_name = to_lower_string(gpm_metric.metricInfo.longName);
    // _per_sec field name suffix is already part of the unit suffix
    field_name = remove_string_suffix(field_name, "_per_sec");
    return std::format("{}_{}", field_name, unit_to_suffix(gpm_metric.metricInfo.unit));
}

