#include "Kernel.h"
#include <Arduino.h>

namespace Lenia {

Kernel::Kernel(uint8_t radius, Type type)
    : radius_(radius)
    , diameter_(2 * radius + 1)
    , size_(diameter_ * diameter_)
    , sum_(0.0f)
{
    // Allocate kernel buffer
    kernel_ = std::unique_ptr<float[]>(new float[size_]);

    // Compute and normalize
    compute(type);
    normalize();

    Serial.printf("Kernel initialized: R=%d, diameter=%d, sum=%.6f\n",
             radius_, diameter_, sum_);
}

void Kernel::compute(Type type) {
    const int8_t center = radius_;
    const float radius_float = static_cast<float>(radius_);

    for (int8_t dy = -center; dy <= center; ++dy) {
        for (int8_t dx = -center; dx <= center; ++dx) {
            // Compute normalized distance
            float dist = std::sqrt(dx * dx + dy * dy);
            float r = dist / radius_float;

            // Apply kernel function
            float value = kernelShell(r, type);

            // Store in buffer
            uint16_t idx = (dy + center) * diameter_ + (dx + center);
            kernel_[idx] = value;
            sum_ += value;
        }
    }
}

void Kernel::normalize() {
    if (sum_ <= 0.0f) {
        Serial.println("ERROR: Kernel sum is zero!");
        return;
    }

    const float inv_sum = 1.0f / sum_;
    for (uint16_t i = 0; i < size_; ++i) {
        kernel_[i] *= inv_sum;
    }
    sum_ = 1.0f;
}

float Kernel::get(int8_t dx, int8_t dy) const {
    // Check bounds
    if (std::abs(dx) > radius_ || std::abs(dy) > radius_) {
        return 0.0f;
    }

    // Convert to array index
    uint16_t idx = (dy + radius_) * diameter_ + (dx + radius_);
    return kernel_[idx];
}

float Kernel::kernelShell(float r, Type type) {
    switch (type) {
        case Type::BUMP4:
            return bump4(r);

        case Type::POLYNOMIAL:
            return polynomial(r);

        case Type::STEP: {
            constexpr float q = 0.25f;
            return (r >= q && r <= 1.0f - q) ? 1.0f : 0.0f;
        }

        default:
            return 0.0f;
    }
}

