int main() {
	std::cout << "Hello world!";	//To print a text

	//Traditional initialization

	int a;							//default initialization, often use for unpredictable variable's values (these variables are called "")
	a = 5;							//copy-initialization, initialization inherited from C, less efficient in modern C++
	int b(6);						//direct initialization, efficient for complex objects, but had fallen out of favor in modern C++ 
	std::cout << a;					//Prints the value of a						

	//Modern initialization (prefferd)

	int x{};						//value-initialisation, in most cases, it implicitly initialize the variable to 0
	int y{ 7 };						/*direct - list - initialization, works in almost all cases, and disallow narrow conversion
									int y{7.5}; will occur an error*/

	//List-initialization disallows narrowing conversions

	int d (8.5);
	int e = 8.5;
	std::cout << d;					//Will 2 times print 8, because these initializations convert the fractional value to an integer
	std::cout << e;

	//When use value-initialization, and when use zero ?

	int f{ 0 };						//0 when we directly use this value
	std::cout << f;
	int g{};						//value-initialization when we imediatly replacing this value
	std::cin >> g;

	//Multiple initialization

	int h = 1, i = 2;				//Correct : h and i got their respective value
	int j, k = 3;					//Wrong ! : j didn't get its value !

	//The [[maybe_unused]] attribute

	[[maybe_unused]] double pi{ 3.14 };	/*If we are not sure to use a value, it's better to put the [[maybe_unused]] attribute
										(they have no performance impact)*/
	std::cout << pi << '\n';

	//THE IOSTREAM LIBRARY
	//std::cout << ;

	int l{ 6 };
	std::cout << "a value: " << 4 << " variable's value: " << l;	//we can concatenate many pieces of output, both text and values
	std::cout << " it's better to change the line..." << std::endl;	//To go on the next line, use "std::endl;" at the end of std::cout
	std::cout << "Or like this :" << "\n";					//but "\n" is better than std::endl, because it's more efficient (doesn't flush the buffer)

	//std::cin >> ;

	std::cout << "Enter a number: ";
	int m{}, n{}, o{};				
	std::cin >> m;					//we can attribute a value to the variable in the console. It automatically go to the next line (enter = \n)
	std::cout << "Enter 2 other numbers: ";
	std::cin >> n >> o;				//and we can even enter 2 values
	std::cout << "value of m: " << m << "value of n: " << n << "value of o: " << o << "\n";

	//Basic extraction process

	int p{};
	std::cout << "Write a number with letters: ";
	std::cin >> p;
	std::cout << "What the program extracted: " << p << "\n";
	/*The steps in extraction:
	1) If we write a number, and then enter, the value is copy-assigned to the variable, and go to the next std::cin
	----------------------------------------------------------------------------------------------------------------------------------------------------
	2) If we write numbers separated by space or tab (for example "45 7 96"), the first number will be copy-assigned to the first operator, and the next
	ones will copy-assigned to the next operators, until reaching an unfilled operator 
	----------------------------------------------------------------------------------------------------------------------------------------------------
	2) If we write nothing (enter, space, tab), the opperator >> will wait for more data
	----------------------------------------------------------------------------------------------------------------------------------------------------
	3) If we write for example "45fkhfrfjzf", the program will extract what it can from the beginning (so here 45), and the next std::cin will fail, and
	the values for each variable will placed to 0
	----------------------------------------------------------------------------------------------------------------------------------------------------
	4) If we write "kkk788" or only characters like this : "effjiihuu", all the extractions will fail, because the first character is not a number
	----------------------------------------------------------------------------------------------------------------------------------------------------
	5) If we write a calculation, like "5+5" or "86-39", it will separate the 2 numbers for 2 input asignements
	----------------------------------------------------------------------------------------------------------------------------------------------------
	REMARK : here the variable is declared as an integer, but if it was declared as a character, it should also fail if it encounters a number first
	*/

	//THE UNINITIALIZED VARIABLES

