void ChatDialog::recvMsg()
{
    MessageHeader msg;
    m_sock->read((char*)&msg, sizeof(msg));

    if(msg.msg_type == MSG_TYPE_TEXT)
    {
        QByteArray data = m_sock->readAll();
        ui->edtReconrd->appendPlainText(QString::fromUtf8(data) + "\n\n");
    }
    else if(msg.msg_type == MSG_TYPE_FILE)
    {
        QString filePath = QFileDialog::getOpenFileName(this, "选择保存的位置", msg.filename);
        QFile file(filePath);
        if (!file.open(QIODevice::WriteOnly|QIODevice::Truncate)) {
            QMessageBox::warning(this, "错误", "无法打开文件");
            return;
        }
        char buff[4 * 1024];
        qint64 ret;

        while ((ret = m_sock->read(buff, sizeof(buff))) > 0)
        {
            file.write(buff, ret);
        }
    }
}


void ChatDialog::on_btnSend_clicked()
{
    QString msg = ui->edtMsg->toPlainText();

    header.msg_type = MSG_TYPE_TEXT;
    header.data_len = msg.toUtf8().size();
    memset(header.filename, 0, sizeof(header.filename));

    m_sock->write((const char*)&header, sizeof(header));
    m_sock->write(msg.toUtf8());
}


void ChatDialog::on_btnSendFile_clicked()
{
    QString filePath = QFileDialog::getOpenFileName(this, "选择要传输的文件");

    QFile file(filePath);
    if (!file.open(QIODevice::ReadOnly)) {
        QMessageBox::warning(this, "错误", "无法打开文件");
        return;
    }

    QFileInfo f(filePath);
    header.msg_type = MSG_TYPE_FILE;
    header.data_len = f.size();

    // 将QString转换为char数组
    QByteArray fb = f.fileName().toUtf8();
    memset(header.filename, 0, sizeof(header.filename));
    strncpy(header.filename, fb.constData(), sizeof(header.filename) - 1);

    // 发送消息头
    m_sock->write((const char*)&header, sizeof(header));

    m_sock->write(file.readAll());

    file.close();
}
