constexpr uint8_t RESP_SUCCESS = 0xC1;

void SerialReceiver::begin(OnUpdate onUpdate)
{
    this->onUpdate = onUpdate;

    Serial.begin(BAUD_RATE);
    // wait for the serial USB-CDC connection to open (needed for Arduino Leonardo and Due)
    while (!Serial)
    {
        // nop
    }
}

void SerialReceiver::process()
{
    // read available serial data
    for (int d = Serial.read(); d != -1; d = Serial.read())
    {
        // detect and handle timeout
        unsigned long t = millis();
        if (t - lastCommTime >= TIMEOUT_MS)
        {
            // on timeout, start from the beginning
            state = RECEIVE_BLOCK_START;
        }
        lastCommTime = t;

        // handle current communication state
        switch (state)
        {
        case RECEIVE_BLOCK_START:
            switch (d)
            {
            case BLOCK_START:
                state = RECEIVE_COMMAND;
                break;
            default:
                // on error, keep same state
                continue;
            }
            break;

        case RECEIVE_COMMAND:
            switch (d)
            {
            case CMD_DMX_96:
                channelCount = 96;
                break;
            case CMD_DMX_256:
                channelCount = 256;
                break;
            case CMD_DMX_512:
                channelCount = 512;
                break;
            default:
                // on error, start from the beginning
                state = RECEIVE_BLOCK_START;
                continue;
            }
            index = 0;
            state = RECEIVE_CHANNELS;
            break;

        case RECEIVE_CHANNELS:
            buffer[index++] = d;
            // all channels received?
            if (index == channelCount)
            {
                state = RECEIVE_BLOCK_END;
            }
            break;

        case RECEIVE_BLOCK_END:
            switch (d)
            {
            case BLOCK_END:
                // received a valid block
                onUpdate(buffer, channelCount);
                // send acknowledge
                Serial.write(BLOCK_START);
                Serial.write(RESP_SUCCESS);
                Serial.write(BLOCK_END);
                break;
            default:
                // on error, nop
                break;
            }
            // always start from the beginning
            state = RECEIVE_BLOCK_START;
            break;
        }
    }
}
