const int MAX_Student = 20;

struct studentType {
    string studentFirstName;
    string studentLastName;
    int testScore;
    char grade;
};

void readStudentData(studentType students[], int& numStudents) {
    cout << "Enter number of students (max " << MAX_Student << "): ";
    cin >> numStudents;
    cin.ignore();

    for (int i = 0; i < numStudents; i++) {
        cout << "Enter first name of student " << (i + 1) << ": ";
        getline(cin, students[i].studentFirstName);
        cout << "Enter last name of student " << (i + 1) << ": ";
        getline(cin, students[i].studentLastName);
        cout << "Enter test score of student " << (i + 1) << ": ";
        cin >> students[i].testScore;
        cin.ignore();
    }
}

void assignGrades(studentType students[], int numStudents) {
    for (int i = 0; i < numStudents; i++) {
        if (students[i].testScore >= 90)
            students[i].grade = 'A';
        else if (students[i].testScore >= 80)
            students[i].grade = 'B';
        else if (students[i].testScore >= 70)
            students[i].grade = 'C';
        else if (students[i].testScore >= 60)
            students[i].grade = 'D';
        else
            students[i].grade = 'F';
    }
}

int findHighestScore(studentType students[], int numStudents) {
    int highest = students[0].testScore;
    for (int i = 1; i < numStudents; i++) {
        if (students[i].testScore > highest) {
            highest = students[i].testScore;
        }
    }
    return highest;
}

void displayStudentData(const studentType students[], int numStudents, int highestScore) {
    cout << fixed << setprecision(2);
    cout << "\nStudent Data:\n";
    cout << "-------------------------------\n";
    cout << "Name\t\tScore\tGrade\n";
    cout << "-------------------------------\n";

    for (int i = 0; i < numStudents; i++) {
        cout << students[i].studentLastName << " " << students[i].studentFirstName << "\t"
             << students[i].testScore << "\t" 
             << students[i].grade << "\n";
    }
    cout << "-------------------------------\n";
}

void printhighestscore (string firstName, string lastName, int highestScore) {
    cout << "\nHighest Score: " << highestScore << " by " << lastName << " " << firstName << "\n";
}
 int main() {
    studentType students[MAX_Student];
    int numStudents;

    readStudentData(students, numStudents);
    assignGrades(students, numStudents);
    int highestScore = findHighestScore(students, numStudents);

    string topFirstName, topLastName;
    for (int i = 0; i < numStudents; i++) {
        if (students[i].testScore == highestScore) {
            topFirstName = students[i].studentFirstName;
            topLastName = students[i].studentLastName;
            break; 
        }
    }

    displayStudentData(students, numStudents, highestScore);
    printhighestscore(topFirstName, topLastName, highestScore);

    return 0;
}
#include"BPE.h"
void read_token(json& x){
    std::ifstream f("data/tokens.json");
    std::string temp;
    f >> temp;
    f.close();
    f.open("data/tokens.json");
    if(temp.empty()) {
        x = json::object();
    }else {
        f >> x;
    }
    f.close();
}
int main() {
    clock_t start_time = clock();
    json tokens;
    read_token(tokens);
    std::ofstream prevo("data/prev_tokens.json", std::ios::out | std::ios::trunc);
    prevo << std::setw(4) << tokens << std::endl;
    prevo.close();
    BPE bpe;
    bpe.import_token(tokens);
    std::ifstream punc_f("materials/punc.txt");
    std::set<Char> Punc;
    Punc.insert(U' ');      // ASCII 空格
    Punc.insert(U'\t');     // 制表符
    Punc.insert(U'\n');     // 换行（如果需要）
    Punc.insert(U'\r');     // 回车
    Punc.insert(U'\u00A0'); // NBSP
    Punc.insert(U'\u3000'); // 全角空格
    String punc;
    getline(punc_f, punc);
    // std::cerr << punc << "\n";
    std::cerr << punc.size() << " punctuation characters loaded.\n";
    for(auto& i : punc){
        Punc.insert(i);
    }
    punc_f.close();
    std::ifstream text_f("materials/text.txt");

    int t = 3000;
    String para;
    // 使用 getline 的返回值作为循环条件，避免在流状态为 fail/EOF 时误用 continue
    while(t-- && getline(text_f, para)) {
        if(para.empty()) {t ++; continue;}
        std::cerr << "Reading paragraph...\n";
        std::cerr << "Training on a paragraph of size " << para.size() << ".\n";
        json current_tokens;
        read_token(current_tokens);
        bpe.import_token(current_tokens);

        std::ofstream o("data/tokens.json", std::ios::out | std::ios::trunc);
        /*删*/
        bool Continue = bpe.train_BPE(para, Punc);
        std::cerr << bpe.Amount_Subword() << " subwords trained.\n";    
        bpe.token_encode();
        json a = bpe.export_token();
        o << std::setw(4) << a << std::endl;
        o.close();
        std::ofstream save("data/tokens.json.old", std::ios::out | std::ios::trunc);
        save << std::setw(4) << current_tokens << std::endl;
        save.close();
        /*输出json */
        if(text_f.eof()) {
            break;
        }
        if(!Continue) {
            std::cerr << "Vocabulary size limit reached. Stopping training.\n";
            break;
        }
    }
    text_f.close();
    std::cerr << "Training completed in " << double(clock() - start_time) / CLOCKS_PER_SEC << " seconds.\n";
    return 0;
}
