#include <iostream>
#include <stack>
#include <vector>
#include <string>
#include <sstream>
using namespace std;

struct Node {
    string data;
    Node* left;
    Node* right;
    Node(string val) : data(val), left(nullptr), right(nullptr) {}
};

vector<string> tokenize(const string& expression) {
    vector<string> tokens;
    stringstream ss(expression);
    string token;
    while (ss >> token) tokens.push_back(token);
    return tokens;
}

class ExpressionTree {
private:
    Node* root;

    void preOrder(Node* node) {
        if (!node) return;
        cout << node->data << " ";
        preOrder(node->left);
        preOrder(node->right);
    }

    void inOrder(Node* node) {
        if (!node) return;
        if (node->left) cout << "(";
        inOrder(node->left);
        cout << node->data;
        inOrder(node->right);
        if (node->right) cout << ")";
    }

    void postOrder(Node* node) {
        if (!node) return;
        postOrder(node->left);
        postOrder(node->right);
        cout << node->data << " ";
    }

public:
    ExpressionTree() : root(nullptr) {}

    void buildTree(const vector<string>& tokens) {
        stack<Node*> Pila;
        for (auto& token : tokens) {
            if (token == "+" || token == "-" || token == "*" || token == "/") {
                Node* right = Pila.top(); 
                Pila.pop();
                Node* left = Pila.top();
                Pila.pop();
                Node* newNode = new Node(token);
                newNode->left = left;
                newNode->right = right;
                Pila.push(newNode);
            } else {
                Pila.push(new Node(token));
            }
        }
        root = Pila.top();
    }

    void printPreOrder() {
        preOrder(root);
        cout << endl;
    }

    void printInOrder() {
        inOrder(root);
        cout << endl;
    }

    void printPostOrder() {
        postOrder(root);
        cout << endl;
    }
};

int main() {
    ExpressionTree tree;
    int opcion;
    string expresion;
    bool bucle=true;
    while(bucle) {
        cout << "\n*** Sistema de Arboles de Expresion ***\n";
        cout << "1. Ingresar expresion postfija\n";
        cout << "2. Mostrar Pre-Orden\n";
        cout << "3. Mostrar In-Orden\n";
        cout << "4. Mostrar Post-Orden\n";
        cout << "5. Salir\n";
        cout << "Opcion: ";
        cin >> opcion;
        cin.ignore();

        if (opcion == 1) {
            cout << "Ingrese la expresion postfija (ej. 10 5 + 3 *): ";
            getline(cin, expresion);
            vector<string> tokens = tokenize(expresion);
            tree.buildTree(tokens);
            cout << "Arbol construido exitosamente.\n";
        } else if (opcion == 2) {
            cout << "Recorrido Pre-Orden:\n";
            tree.printPreOrder();
        } else if (opcion == 3) {
            cout << "Recorrido In-Orden:\n";
            tree.printInOrder();
        } else if (opcion == 4) {
            cout << "Recorrido Post-Orden:\n";
            tree.printPostOrder();
        } else if (opcion == 5){
            cout << "Saliendo del programa.\n";
            bucle = false;
        }

    };

}
