using namespace std;

void clientHandler(SOCKET socket) {
    string message = "Hello from server";
    send(socket, message.c_str(), message.size(), 0);

    char buffer[1024];
    memset(buffer, '\0', sizeof(buffer));
    int bytes_received = recv(socket, buffer, sizeof(buffer) - 1, 0);

    if (bytes_received > 0) {
        buffer[bytes_received] = '\0';
        string newStr = string(buffer);

        for (int i = 0; i + 1 < newStr.size(); i += 2) {
            swap(newStr[i], newStr[i + 1]);
        }

        send(socket, newStr.c_str(), newStr.size(), 0);
        cout << "Обработана строка: " << buffer << " -> " << newStr << endl;
    }

    closesocket(socket);
}

int main() {
    SetConsoleCP(CP_UTF8);
    SetConsoleOutputCP(CP_UTF8);

    int availableConnections = 10;
    vector<thread*> threads(availableConnections, nullptr);

    WSADATA wsaData;
    if (WSAStartup(MAKEWORD(2, 2), &wsaData) != 0) {
        cout << "WSAStartup failed with error: " << WSAGetLastError() << endl;
        return 1;
    }

    SOCKET serverSocket = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (serverSocket == INVALID_SOCKET) {
        cout << "socket failed with error: " << WSAGetLastError() << endl;
        WSACleanup();
        return 1;
    }

    SOCKADDR_IN addr;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(1234);

    if (bind(serverSocket, (struct sockaddr*)&addr, sizeof(addr)) == SOCKET_ERROR) {
        cout << "bind failed with error: " << WSAGetLastError() << endl;
        closesocket(serverSocket);
        WSACleanup();
        return 1;
    }

    if (listen(serverSocket, 10) == SOCKET_ERROR) {
        cout << "listen failed with error: " << WSAGetLastError() << endl;
        closesocket(serverSocket);
        WSACleanup();
        return 1;
    }

    cout << "Сервер запущен и ожидает подключений..." << endl;

    for (int i = 0; i < availableConnections; i++) {
        SOCKADDR_IN clientAddr;
        int clientAddrSize = sizeof(clientAddr);

        SOCKET clientSocket = accept(serverSocket, (struct sockaddr*)&clientAddr, &clientAddrSize);

        if (clientSocket == INVALID_SOCKET) {
            cout << "accept failed with error: " << WSAGetLastError() << endl;
            continue;
        }
        else {
            cout << "Новый клиент подключен! Создание потока " << i << endl;

            // ЗАХВАТ ПО ССЫЛКЕ, но с отдельной переменной для каждого потока
            SOCKET socketForThread = clientSocket;
            threads[i] = new thread([&socketForThread]() {
                clientHandler(socketForThread);
            });
        }
    }

    for (int i = 0; i < availableConnections; i++) {
        if (threads[i] != nullptr) {
            threads[i]->join();
            delete threads[i];
        }
    }

    closesocket(serverSocket);
    WSACleanup();
    return 0;
}
