void PostPass::cleanup()
{
	if (targetFBO)
	{
		glDeleteFramebuffers(1, &targetFBO);
		targetFBO = 0;

		glDeleteTextures(1, &targetTex);
		targetTex = 0;

		width = 1;
		height = 1;
		internalFormat = 0;
		format = 0;
		formatType = 0;
	}
}

PostPass::~PostPass()
{
	cleanup();
}

