TEST_CASE("deterministic_replay") {
    OrderBook book1, book2;

    // Replay same sequence twice
    std::vector<std::tuple<Side, Price, Quantity>> events = {
        {Side::Buy, 10000, 100},
        {Side::Sell, 10000, 50},
        {Side::Buy, 10050, 200},
        {Side::Sell, 10040, 75}
    };

    // First run
    for (auto [side, price, qty] : events) {
        book1.submit_limit_simple(side, price, qty);
    }

    // Second run
    for (auto [side, price, qty] : events) {
        book2.submit_limit_simple(side, price, qty);
    }

    // Should have same state
    auto bid1 = book1.best_bid();
    auto bid2 = book2.best_bid();
    CHECK_EQ(bid1.has_value(), bid2.has_value());
    if (bid1.has_value()) {
        CHECK_EQ(*bid1, *bid2);
    }

    auto ask1 = book1.best_ask();
    auto ask2 = book2.best_ask();
    CHECK_EQ(ask1.has_value(), ask2.has_value());
    if (ask1.has_value()) {
        CHECK_EQ(*ask1, *ask2);
    }

    // Total resting qty should match
    CHECK_EQ(book1.total_resting_qty(Side::Buy), book2.total_resting_qty(Side::Buy));
    CHECK_EQ(book1.total_resting_qty(Side::Sell), book2.total_resting_qty(Side::Sell));
}

