Process::Process(int pid)
    : prev_usr_time(0),
      prev_sys_time(0),
      pid(pid),
      cpu_usage(0.0f),
      mem_usage(0) {}

void Process::update_stats(unsigned long prev_total, unsigned long curr_total) {
    const std::string stat_path =
        "/proc/" + std::to_string(this->pid) + "/stat";
    const std::string content = this->reader.read_file(stat_path);
    if (content.empty()) return;

    // because process name can contain spaces and is enclosed in parentheses
    size_t last_paren = content.rfind(')');
    if (last_paren == std::string::npos) return;

    // remove parentheses from name
    size_t first_paren = content.find('(');
    if (first_paren != std::string::npos) {
        this->name =
            content.substr(first_paren + 1, last_paren - first_paren - 1);
    }

    // will allow us to iterate content word by word
    // it seperates content by white spaces and starts from after last
    // parenthesis
    std::istringstream stream(content.substr(last_paren + 2));
    // retrieve process state
    stream >> this->state;

    int skip;
    // skip to the fields we need (field 14 utime and 15 stime)
    for (int i = 0; i < 10; i++) {
        stream >> skip;
    }

    unsigned long utime, stime;
    stream >> utime >> stime;

    // calculate cpu usage of process
    if (prev_total > 0) {
        // how much time this process used
        unsigned long processTimeUsed =
            (utime + stime) - (this->prev_usr_time + this->prev_sys_time);

        // how mych time passed for everyone (all processes)
        // currTotal and prevTotal will be passed from system monitor
        unsigned long totalTimePassed = curr_total - prev_total;

        if (totalTimePassed > 0) {
            // number of cpu cores
            static int num_cores = std::thread::hardware_concurrency();

            this->cpu_usage =
                (100.0f * processTimeUsed) /
                (totalTimePassed *
                 num_cores);  // normalize by number of cores of the cpu
        }
    }

    this->prev_usr_time = utime;
    this->prev_sys_time = stime;

    // get memory usage from /proc/<pid>/status
    const std::string status_path =
        "/proc/" + std::to_string(this->pid) + "/status";
    const std::string status_content = this->reader.read_file(status_path);

    // ex: VmRSS: 9200kB
    size_t pos = status_content.find("VmRSS:");
    if (pos != std::string::npos) {
        // pos + 6 because between "VmRSS: val" is 6 spaces
        std::istringstream memory_stream(status_content.substr(pos + 6));
        memory_stream >> this->mem_usage;
    }
}

#include <bits/stdc++.h>
using namespace std;

bool load_words(const string& path, vector<pair<string,int>>& out) {
    ifstream in(path);
    if (!in) return false;
    string line;
    while (getline(in, line)) {
        if (line.empty()) continue;
        istringstream iss(line);
        string w;
        long long freqll = 0;
        if (!(iss >> w)) continue;
        if (!(iss >> freqll)) freqll = 0;
        if (freqll > INT_MAX) freqll = INT_MAX;
        out.emplace_back(w, static_cast<int>(freqll));
    }
    sort(out.begin(), out.end(), [](const pair<string,int>& a, const pair<string,int>& b){
        return a.first < b.first;
    });
    return true;
}

// returns up to k pairs (word,freq) sorted by freq desc, then word asc
vector<pair<string,int>> autocomplete(const vector<pair<string,int>>& words, const string& prefix, int k) {
    vector<pair<string,int>> res;
    if (prefix.empty() || words.empty() || k <= 0) return res;

    auto comp_elem_vs_str = [](const pair<string,int>& a, const string& b){
        return a.first < b;
    };
    string prefix_upper = prefix;
    prefix_upper.push_back(char(127)); 
    auto it_low = lower_bound(words.begin(), words.end(), prefix, comp_elem_vs_str);
    auto it_up  = lower_bound(words.begin(), words.end(), prefix_upper, comp_elem_vs_str);
    if (it_low == it_up) return res;

    struct Node { int freq; const string* w; };
    struct Cmp {
        bool operator()(const Node& a, const Node& b) const {
            if (a.freq != b.freq) return a.freq > b.freq;
            return *(a.w) < *(b.w);
        }
    };
    priority_queue<Node, vector<Node>, Cmp> pq;
    for (auto it = it_low; it != it_up; ++it) {
        Node n{it->second, &it->first};
        if ((int)pq.size() < k) pq.push(n);
        else {
            const Node& top = pq.top();
            if (n.freq > top.freq || (n.freq == top.freq && *(n.w) < *(top.w))) {
                pq.pop();
                pq.push(n);
            }
        }
    }
    while (!pq.empty()) {
        res.emplace_back(*pq.top().w, pq.top().freq);
        pq.pop();
    }
    reverse(res.begin(), res.end());
    return res;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        cerr << "Usage: " << argv[0] << " words.txt [K]" << endl;
        return 1;
    }
    string words_file = argv[1];
    int K = 5;
    if (argc >= 3) {
        try { K = stoi(argv[2]); } catch(...) { K = 5; }
        if (K <= 0) K = 5;
    }

    vector<pair<string,int>> words;
    if (!load_words(words_file, words)) {
        cerr << "Failed to load words from '" << words_file << "'." << endl;
        cerr << "Expected file format: one line per entry: word [frequency]" << endl;
        return 1;
    }

    cout << "Loaded " << words.size() << " entries. Top-K = " << K << "\n\n";

    while (true) {
        cout << "Enter prefix (or 'exit' to quit): ";
        string prefix;
        if (!getline(cin, prefix)) break;
        if (prefix == "exit") break;

        vector<pair<string,int>> suggestions = autocomplete(words, prefix, K);
        if (suggestions.empty()) {
            cout << "No matches found.\n\n";
            continue;
        }

        cout << "Suggestions:\n";
        for (size_t i = 0; i < suggestions.size(); ++i)
            cout << "  " << (i+1) << ". " << suggestions[i].first << " (" << suggestions[i].second << ")\n";
        cout << "\n";
    }

    cout << "Goodbye!\n";
    return 0;
}
