ScriptProvider::ScriptProvider(Context &context) noexcept
    : _context(context),
      _versionID(-1),
      _latestScriptID(0),
      _scriptID2Data(),
      _scriptName2ID()
{
	// 监听脚本文件夹
	_fileWatch = std::make_unique<filewatch::FileWatch<std::string>>(std::string(ScriptDirectory), [this](const std::string &path, const filewatch::Event changeType)
	{
		std::string scriptName = Utils::PathToLuaScriptName(path, ScriptDirectory);

		std::lock_guard<std::mutex> lock{_watchMutex};

		switch (changeType)
		{
		case filewatch::Event::added:
		case filewatch::Event::renamed_new:
		{
			UTILS_LOG("文件添加：{}", scriptName);
			std::string code = ReadScriptCode(path);
			AddScript(scriptName, code);
			break;
		}
		case filewatch::Event::removed:
		case filewatch::Event::renamed_old:
		{
			UTILS_LOG("文件移除：{}", scriptName);
			assert(RemoveScript(scriptName));
			break;
		}
		case filewatch::Event::modified:
		{
			UTILS_LOG("文件更改：{}", scriptName);
			assert(RemoveScript(scriptName));
			std::string code = ReadScriptCode(path);
			AddScript(scriptName, code);
			break;
		}
		default:
			std::abort();
		}
	});

	std::lock_guard<std::mutex> lock{_watchMutex};

	// 添加所有脚本文件
	for (const auto &entry : std::filesystem::recursive_directory_iterator(ScriptDirectory))
	{
		if (entry.is_regular_file() && entry.path().extension() == ".lua")
		{
			std::ifstream file{entry.path()};
			if (file)
			{
				std::string code{(std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>()};
				AddScript(Utils::PathToLuaScriptName(entry.path().generic_string(), ScriptDirectory), code);
			}
		}
	}
}

std::string ScriptProvider::ReadScriptCode(std::string_view path) noexcept
{
	auto filePath = std::string(ScriptDirectory)
	                    .append("/")
	                    .append(path);
	std::ifstream fileStream{filePath};

	std::string code = std::string((std::istreambuf_iterator<char>(fileStream)), std::istreambuf_iterator<char>());
	return code;
}

std::uint32_t ScriptProvider::GetVersionID() const noexcept
{
	std::lock_guard<std::mutex> lock{_watchMutex};

	return _versionID;
}

std::size_t ScriptProvider::GetScriptsCount() const noexcept
{
	std::lock_guard<std::mutex> lock{_watchMutex};

	return _scriptID2Data.size();
}

bool ScriptProvider::ContainsScript(std::uint32_t scriptID) const noexcept
{
	std::lock_guard<std::mutex> lock{_watchMutex};

	return _scriptID2Data.contains(scriptID);
}

bool ScriptProvider::ContainsScript(std::string_view scriptName) const noexcept
{
	std::lock_guard<std::mutex> lock{_watchMutex};

	return _scriptName2ID.contains(scriptName);
}

std::uint32_t ScriptProvider::GetScriptID(std::string_view scriptName) const noexcept
{
	std::lock_guard<std::mutex> lock{_watchMutex};

	if (auto it = _scriptName2ID.find(scriptName); it != _scriptName2ID.end())
	{
		return it->second;
	}
	else
	{
		return 0;
	}
}

std::string_view ScriptProvider::GetScriptName(std::uint32_t scriptID) const noexcept
{
	std::lock_guard<std::mutex> lock{_watchMutex};

	if (auto it = _scriptID2Data.find(scriptID); it != _scriptID2Data.end())
	{
		return it->second.name;
	}
	else
	{
		return "";
	}
}

std::string_view ScriptProvider::GetScriptCode(std::uint32_t scriptID) const noexcept
{
	std::lock_guard<std::mutex> lock{_watchMutex};
	if (auto it = _scriptID2Data.find(scriptID); it != _scriptID2Data.end())
	{
		return it->second.code;
	}
	else
	{
		return "";
	}
}

void ScriptProvider::AddScript(std::string_view scriptName, std::string_view scriptCode) noexcept
{
	if (scriptName.empty()) [[unlikely]]
	{
		std::abort(); // Script's name cannot be empty
	}

	++_versionID;
	++_latestScriptID;
	_scriptsCache = nullptr;

	ScriptData data{
	    .id = _latestScriptID,
	    .name = std::string(scriptName),
	    .code = std::string(scriptCode),
	};
	const ScriptData &data1 = _scriptID2Data.emplace(data.id, data).first->second;
	_scriptName2ID.emplace(data1.name, data1.id);

	UTILS_LOG("添加脚本：<{}>{}, 共{}字节", data1.id, data1.name, data1.code.size());
}

bool ScriptProvider::RemoveScript(std::uint32_t scriptID) noexcept
{
	auto it = _scriptID2Data.find(scriptID);
	if (it == _scriptID2Data.end())
	{
		return false;
	}

	std::string scriptName = it->second.name;

	++_versionID;
	_scriptsCache = nullptr;

	_scriptName2ID.erase(scriptName);
	_scriptID2Data.erase(it);

	UTILS_LOG("移除脚本：<{}>{}", scriptID, scriptName);

	return true;
}

bool ScriptProvider::RemoveScript(std::string_view scriptName) noexcept
{
	if (auto it = _scriptName2ID.find(scriptName); it != _scriptName2ID.end())
	{
		return RemoveScript(it->second);
	}
	else
	{
		return false;
	}
}

