    SortStats bubbleSort(std::vector<int>& arr, bool ascending) {
        SortStats stats;
        const std::size_t n = arr.size();
        for (std::size_t i = 0; i < n - 1; ++i) {
            for (std::size_t j = 0; j < n - i - 1; ++j) {
                stats.comparisons++;
                if ((ascending && arr[j] > arr[j + 1]) ||
                    (!ascending && arr[j] < arr[j + 1])) {
                    stats.swaps++;
                    std::swap(arr[j], arr[j + 1]);
                }
            }
        }
        return stats;
    }

    SortStats selectionSort(std::vector<int>& arr, bool ascending) {
        SortStats stats;
        const std::size_t n = arr.size();
        for (std::size_t i = 0; i < n - 1; ++i) {
            std::size_t best = i;
            for (std::size_t j = i + 1; j < n; ++j) {
                stats.comparisons++;
                if ((ascending && arr[j] < arr[best]) ||
                    (!ascending && arr[j] > arr[best])) {
                    best = j;
                }
            }
            if (best != i) {
                stats.swaps++;
                std::swap(arr[best], arr[i]);
            }
        }
        return stats;
    }

    std::vector<int> generateRandomArray(std::size_t size, int minVal, int maxVal) {
        std::vector<int> arr(size);
        std::random_device rd;
        std::default_random_engine gen(rd());
        std::uniform_int_distribution<int> dist(minVal, maxVal);
        for (std::size_t i = 0; i < size; ++i)
            arr[i] = dist(gen);
        return arr;
    }

