        }
        on.close();
        cout << "+++++++++++++++++++Data Saved Successfully+++++++++++++++++++" << endl;
    }
    else
    {
        cout << "+++++++++++++++++++Data Failed To Save+++++++++++++++++++" << endl;
    }
}

