bool isIntConvertible(std::string str)
{
	auto dotIt = std::find(str.begin(), str.end(), '-');
	if (dotIt != str.end())
	{
		str.erase(dotIt);
	}
	return std::all_of(str.begin(), str.end(), 
			[](char c)
			{
				return std::isdigit(c);
			});
}

bool isFloatConvertible(std::string str)
{
	auto dotIt = std::find(str.begin(), str.end(), '.');
	if (dotIt != str.end())
	{
		str.erase(dotIt);
		return isIntConvertible(str);
	}
	return false;
}

int main(int argc, char **argv)
{
	if (argc < 3)
	{
		std::cout << "Too few arguments" << std::endl;
		std::exit(EXIT_FAILURE);
	}

	std::string topic = argv[1];
	std::string value = argv[2];
	nlohmann::json json;
	if (isIntConvertible(value))
	{
		json[topic] = std::stoi(value);
	}
	else if (isFloatConvertible(value))
	{
		json[topic] = std::stof(value);
	}
	else
	{
		json[topic] = value;
	}

	simple_socket::TCPClientContext client;
	if (const auto conn = client.connect("127.0.0.1", 6969))
