long long memo[MAXN + 1][MAXN + 1];

long long combination_rec(int n, int r) {
	if (r > n) return 0;
	if (r == 0 || r == n) return 1;
	if (memo[n][r] != -1) return memo[n][r];
	return memo[n][r] = combination_rec(n - 1, r) + combination_rec(n - 1, r - 1);
}


