#include <stdio.h>
#include <string.h>

// maximum candidates allowed
#define MAX_C 10

// structure to store candidate info
typedef struct {
    char name[50];
    int votes;
    char symbol;
} Candidate;

Candidate allCandidates[MAX_C];
int candidateCount = 0;
char symbols[10] = { '!', '@', '#', '$', '%', '^', '&', '*', '~', '+' };
int symbolTaken[10];

// function declarations
void fillCandidate(int);
void displayAllCandidates();
void getVote(int);
void showResults();

int main() {
    // initialize symbol tracking
    for (int i = 0; i < 10; i++)
        symbolTaken[i] = 0;

    printf("Enter number of candidates (max 10): ");
    scanf("%d", &candidateCount);

    if (candidateCount <= 0 || candidateCount > 10) {
        printf("? Invalid number of candidates. Program exiting.\n");
        return 0;
    }

    // get candidate details
    for (int i = 0; i < candidateCount; i++) {
        fillCandidate(i);
    }

    int voters;
    printf("\nEnter number of voters: ");
    scanf("%d", &voters);

    if (voters <= 0) {
        printf("? Number of voters must be at least 1.\n");
        return 0;
    }

    // collect votes
    for (int i = 0; i < voters; i++) {
        printf("\nVoting Round %d:\n", i + 1);
        getVote(i);
    }

    // show final results
    showResults();
    return 0;
}

// fill candidate details
void fillCandidate(int index) {
    printf("\nAvailable Symbols:\n");
    for (int i = 0; i < 10; i++) {
        if (!symbolTaken[i]) {
            printf("%d. %c\n", i + 1, symbols[i]);
        }
    }

    int choice;
    printf("Enter symbol number for Candidate %d: ", index + 1);
    scanf("%d", &choice);

    if (choice < 1 || choice > 10 || symbolTaken[choice - 1]) {
        printf("? Invalid or already taken symbol. Try again.\n");
        fillCandidate(index);
        return;
    }

    symbolTaken[choice - 1] = 1;
    allCandidates[index].symbol = symbols[choice - 1];

    printf("Enter name of Candidate %d: ", index + 1);
    scanf("%s", allCandidates[index].name);

    allCandidates[index].votes = 0;
}

// display all candidates
void displayAllCandidates() {
    printf("\n------------------- Candidates -------------------\n");
    for (int i = 0; i < candidateCount; i++) {
        printf("%d. %-15s (Symbol: %c)\n", i + 1, allCandidates[i].name, allCandidates[i].symbol);
    }
    printf("--------------------------------------------------\n");
}

// collect a single vote
void getVote(int voterNum) {
    displayAllCandidates();

    int choice;
    printf("Voter %d, enter your choice (1-%d): ", voterNum + 1, candidateCount);
    scanf("%d", &choice);

    if (choice >= 1 && choice <= candidateCount) {
        allCandidates[choice - 1].votes++;
        printf("? Vote recorded for %s!\n", allCandidates[choice - 1].name);
    } else {
        printf("? Invalid choice. Please try again.\n");
        getVote(voterNum);
    }
}

// display election results
void showResults() {
    printf("\n==================== RESULTS ====================\n");

    int maxVotes = 0;
    for (int i = 0; i < candidateCount; i++) {
        if (allCandidates[i].votes > maxVotes)
            maxVotes = allCandidates[i].votes;
    }

    // show all candidates and their votes
    for (int i = 0; i < candidateCount; i++) {
        printf("%-15s (Symbol: %c) - %d votes\n",
               allCandidates[i].name, allCandidates[i].symbol, allCandidates[i].votes);
    }

    // count how many have maxVotes
    int winners = 0;
    for (int i = 0; i < candidateCount; i++) {
        if (allCandidates[i].votes == maxVotes)
            winners++;
    }

    if (winners > 1) {
        printf("\n?? It's a TIE between the following candidates:\n");
        for (int i = 0; i < candidateCount; i++) {
            if (allCandidates[i].votes == maxVotes)
                printf("- %s (Symbol: %c)\n", allCandidates[i].name, allCandidates[i].symbol);
        }
    } else {
        for (int i = 0; i < candidateCount; i++) {
            if (allCandidates[i].votes == maxVotes) {
                printf("\n?? Winner: %s (Symbol: %c) with %d votes!\n",
                       allCandidates[i].name, allCandidates[i].symbol, allCandidates[i].votes);
                break;
            }
        }
    }

    printf("==================================================\n");
}

