using namespace std;

// Рекурсивна функція створення масиву випадкових дійсних чисел
void create(double* arr, int SIZE, double MIN, double MAX, int i = 0)
{
    if (i >= SIZE) return;
    arr[i] = (MAX - MIN) * rand() / RAND_MAX + MIN;
    create(arr, SIZE, MIN, MAX, i + 1);
}

// Рекурсивна функція виведення масиву
void print(double* arr, int SIZE, int i = 0)
{
    if (i >= SIZE) { cout << endl; return; }
    cout << fixed << setprecision(2) << arr[i] << "  ";
    print(arr, SIZE, i + 1);
}

// Рекурсивна функція підрахунку кількості додатних елементів масиву
int count(double* arr, int SIZE, int i = 0)
{
    if (i >= SIZE) return 0;
    return (arr[i] > 0 ? 1 : 0) + count(arr, SIZE, i + 1);
}

// Рекурсивна функція для обчислення суми елементів після останнього нуля
double sum(double* arr, int SIZE, int i = 0, int lastZeroIndex = -1, bool searchPhase = true)
{
    if (searchPhase)
    {
        if (i == SIZE) return sum(arr, SIZE, lastZeroIndex + 1, lastZeroIndex, false);
        if (arr[i] == 0) lastZeroIndex = i;
        return sum(arr, SIZE, i + 1, lastZeroIndex, true);
    }
    else
    {
        if (i >= SIZE) return 0;
        return arr[i] + sum(arr, SIZE, i + 1, lastZeroIndex, false);
    }
}

// Рекурсивне копіювання елементів, що задовольняють умову
void copyCondition(double* arr, double* temp, int SIZE, int& index, bool firstPart, int i = 0)
{
    if (i >= SIZE) return;

    if ((firstPart && (int)arr[i] <= 1) || (!firstPart && (int)arr[i] > 1))
        temp[index++] = arr[i];

    copyCondition(arr, temp, SIZE, index, firstPart, i + 1);
}

// Рекурсивне копіювання з temp у arr
void copyBack(double* arr, double* temp, int SIZE, int i = 0)
{
    if (i >= SIZE) return;
    arr[i] = temp[i];
    copyBack(arr, temp, SIZE, i + 1);
}

// Рекурсивна функція перестановки елементів
void sort(double* arr, int SIZE)
{
    double* temp = new double[SIZE];
    int index = 0;
    copyCondition(arr, temp, SIZE, index, true);
    copyCondition(arr, temp, SIZE, index, false);
    copyBack(arr, temp, SIZE);
    delete[] temp;
}

