    print(arr, SIZE);
    wcout << endl;

    wcout << L"Кількість додатних елементів масиву: " << count(arr, SIZE) << endl;
    wcout << L"Сума елементів після останнього нуля: " << sum(arr, SIZE) << endl;

    sort(arr, SIZE);

    wcout << endl << L"Масив після перестановки:" << endl;
    print(arr, SIZE);

    delete[] arr;

    return 0;
}
