std::string BFAssert::toString(bool WithMsg) const {
  std::string Out;
  if (Pos == DATA_POINTER)
    Out += "ptr ";
  else
    Out += "[" + std::to_string(Pos) + "] ";

  switch (Type) {
  case EQ:
    Out += "==";
    break;
  case NE:
    Out += "!=";
    break;
  case LT:
    Out += "<";
    break;
  case LE:
    Out += "<=";
    break;
  case GT:
    Out += ">";
    break;
  case GE:
    Out += ">=";
    break;
  default:
    assert(false && "Unknown assert type");
  }

  Out += " " + std::to_string(Val);

  if (WithMsg)
    Out += "," + Msg;

  return Out;
}

BFAssert BFAssert::parse(const std::string &S) {
  auto LHSEnd = S.find_first_of(' ');
  auto TypeEnd = S.find_first_of(' ', LHSEnd + 1);
  auto RHSEnd = S.find_first_of(',', TypeEnd + 1);

  assert(LHSEnd != std::string::npos && TypeEnd != std::string::npos);

  auto LHS = S.substr(0, LHSEnd);
  auto Type = S.substr(LHSEnd + 1, TypeEnd - LHSEnd - 1);
  auto RHS = S.substr(TypeEnd + 1, RHSEnd - TypeEnd - 1);
  auto Msg = S.substr(RHSEnd + 1);

  size_t L;
  if (LHS == "ptr")
    L = DATA_POINTER;
  else {
    assert(!LHS.empty() && LHS[0] == '[' && LHS[LHS.size() - 1] == ']');
    L = std::stoull(LHS.substr(1, LHS.size() - 2));
  }

  AssertType T;
  if (Type == "==")
    T = EQ;
  else if (Type == "!=")
    T = NE;
  else if (Type == "<")
    T = LT;
  else if (Type == "<=")
    T = LE;
  else if (Type == ">")
    T = GT;
  else if (Type == ">=")
    T = GE;
  else
    assert(false);

  int64_t R = std::stoll(RHS);

  return {T, L, R, Msg};
}

std::string formatBrainfuck(const std::vector<BFOpBundle> &Insts, bool Debug) {
  std::string Out;
  Out.reserve(Insts.size() * 2);

  auto NewLine = [&] {
    if (Out.empty() || Out.back() != '\n')
      Out += '\n';
  };

  for (const auto &I : Insts) {
    if (!Debug && I.Op > BFOp::BNEZ)
      continue;

    if (I.Op == BFOp::DbgPrint) {
      NewLine();
      Out += "(" + I.DbgString + ")\n";
      continue;
    }

    if (I.Op == BFOp::DbgComment) {
      NewLine();
      Out += "# " + I.DbgString + "\n";
      continue;
    }

    if (I.Op == BFOp::DbgAssert) {
      NewLine();
      Out += "{" + I.Assert.toString() + "}\n";
      continue;
    }

    char C = 0;
    switch (I.Op) {
#define LLVM_BRAINFUCK_OP_TABLE_ENTRY(NAME, CHAR)                              \
  case BFOp::NAME:                                                             \
    C = CHAR;                                                                  \
    break;

      LLVM_BRAINFUCK_OP_TABLE

#undef LLVM_BRAINFUCK_OP_TABLE_ENTRY

    default:
      assert(false && "Unknown op");
    }

    assert(C != '\0' && "What op?");

    Out += std::string(I.Num, C);
  }

  return Out;
}

bool isBrainfuckBuiltin(llvm::StringRef Name) {
  return Name == "putchar" || Name == "getchar";
}
