using namespace std;

const int NUM_STUDENTS = 20;

struct studentType {
    string studentFName;
    string studentLName;
    int testScore;
    char grade;
};

// Fungsi untuk menginputkan data mahasiswa
void getData(studentType students[], int numStudents) {
    for (int i = 0; i < numStudents; i++) {
        cout << "Enter first name, last name, and test score of student " << i + 1 << ": ";
        cin >> students[i].studentFName >> students[i].studentLName >> students[i].testScore;
    }
}

// Fungsi untuk menentukan grade 
void assignGrade(studentType students[], int numStudents) {
    for (int i = 0; i < numStudents; i++) {
        int score = students[i].testScore;
        if (score >= 90)
            students[i].grade = 'A';
        else if (score >= 80)
            students[i].grade = 'B';
        else if (score >= 70)
            students[i].grade = 'C';
        else if (score >= 60)
            students[i].grade = 'D';
        else
            students[i].grade = 'F';
    }
}

// Fungsi untuk menentukan nilai ujian tertinggi
int highestScore(const studentType students[], int numStudents) {
    int highest = students[0].testScore;
    for (int i = 1; i < numStudents; i++) {
        if (students[i].testScore > highest)
            highest = students[i].testScore;
    }
    return highest;
}

// Fungsi untuk menampilkan nama mahasiswa dengan nilai ujian tertinggi
void printHighest(const studentType students[], int numStudents, int highest) {
    cout << "\nHighest test score: " << highest << endl;
    cout << "Student(s) with the highest score:" << endl;
    for (int i = 0; i < numStudents; i++) {
        if (students[i].testScore == highest)
            cout << "  " << students[i].studentLName << ", " << students[i].studentFName << endl;
    }
}

// Fungsi untuk menampilkan data seluruh mahasiswa
void printAll(const studentType students[], int numStudents) {
    cout << left << setw(20) << "Name"
         << setw(12) << "Score"
         << "Grade" << endl;
    cout << "---------------------------------" << endl;
    for (int i = 0; i < numStudents; i++) {
        string fullName = students[i].studentLName + ", " + students[i].studentFName;
        cout << left << setw(20) << fullName
             << setw(12) << students[i].testScore
             << students[i].grade << endl;
    }
}

int main() {
    studentType students[NUM_STUDENTS];

    getData(students, NUM_STUDENTS);
    assignGrade(students, NUM_STUDENTS);
    printAll(students, NUM_STUDENTS);

    int highest = highestScore(students, NUM_STUDENTS);
    printHighest(students, NUM_STUDENTS, highest);

    return 0;
}
