TransactionDetailsFetcher::TransactionDetailsFetcher(RpcClient& rpc)
    : m_rpc(rpc) {}

TransactionDetails TransactionDetailsFetcher::getTransactionDetails(const std::string& signature) {
    TransactionDetails details;
    details.signature = signature;

    auto response = m_rpc.call("getTransaction", nlohmann::json::array({
        signature,
        nlohmann::json{
            {"encoding", "jsonParsed"},
            {"commitment", "finalized"},
            {"maxSupportedTransactionVersion", 0}
        }
    }));

    if (!response.contains("result")) {
        std::cerr << "⚠️ Tx not found: " << signature << "\n";
        return details;
    }

    const auto& tx = response["result"];
    if (!tx.contains("transaction")) return details;
    const auto& message = tx["transaction"]["message"];
    if (!message.contains("instructions")) return details;

    for (const auto& instr : message["instructions"]) {
        InstructionInfo info;
        info.program = instr.value("program", "");
        if (info.program.empty() && instr.contains("programId")) {
            info.program = instr["programId"].get<std::string>();
        }

        // 🔹 Отсекаем ComputeBudget и прочие системные вызовы
        if (info.program.find("ComputeBudget111") != std::string::npos) continue;

        // 🔹 Распознаём известные программы
        if (info.program.find("11111111111111111111111111111111") != std::string::npos)
            info.program = "system";
        else if (info.program.find("Tokenkeg") != std::string::npos)
            info.program = "spl-token";
        else if (info.program.find("Raydium") != std::string::npos)
            info.program = "raydium";
        else if (info.program.find("JUP") != std::string::npos)
            info.program = "jupiter";

        // 🔍 Проверяем parsed-структуру
        if (instr.contains("parsed") && instr["parsed"].is_object()) {
            info.type = instr["parsed"].value("type", "(parsed)");

            if (instr["parsed"].contains("info") && instr["parsed"]["info"].is_object()) {
                const auto& parsedInfo = instr["parsed"]["info"];

                info.source = parsedInfo.value("source", "");
                info.destination = parsedInfo.value("destination", "");
                info.token = parsedInfo.value("mint", "");

                if (parsedInfo.contains("amount") && parsedInfo["amount"].is_string()) {
                    try {
                        std::string amountStr = parsedInfo["amount"].get<std::string>();
                        double raw = std::stod(amountStr);

                        if (info.program == "system" && info.type == "transfer") {
                            info.amount = raw / 1e9;
                            info.token = "SOL";
                        } else {
                            info.amount = raw / 1e6;
                            if (info.token.empty()) info.token = "SPL";
                        }
                    } catch (...) {
                        // bad formate
                    }
                }
            }
        } else {
            info.type = "(unparsed)";
        }

        details.instructions.push_back(info);
    }

    // Delay for api
    std::this_thread::sleep_for(std::chrono::milliseconds(50));

    return details;
}
/**
 * @file main.cpp
 * @brief LFG (Looking For Group) Dungeon Queue - Deadlock/Starvation-Free Implementation
 * 
 * ==========================================================================================
 * OVERVIEW
 * ==========================================================================================
 * This program simulates an MMORPG dungeon matchmaking system with n concurrent instances.
 * Each party requires exactly 1 Tank + 1 Healer + 3 DPS players.
 * 
 * ==========================================================================================
 * ARCHITECTURE
 * ==========================================================================================
 * Thread Model:
 *   1. Main thread (producer): Forms parties and pushes to queue
 *   2. n worker threads (consumers): Pop parties, simulate dungeons, update metrics
 *   3. Reporter thread: Prints live status every ~1 second
 *   4. (Optional) Late arrival thread: Adds random players during runtime
 * 
 * Synchronization:
 *   - PartyJobQueue: Single mutex + 2 CVs (push/pop), bounded capacity
 *   - InstanceMetrics: Atomic variables (lock-free reads/writes)
 *   - Reporter wakeup: g_status_cv + g_status_mx
 * 
 * ==========================================================================================
 * DEADLOCK PREVENTION
 * ==========================================================================================
 * 1. Single lock per resource (queue has one mutex, metrics are atomic)
 * 2. No nested locks (workers never hold multiple mutexes)
 * 3. Lock released before sleep (workers release queue mutex before simulating dungeon)
 * 4. One-way dependencies: main → queue ← workers (no circular wait)
 * 
 * ==========================================================================================
 * STARVATION PREVENTION
 * ==========================================================================================
 * 1. FIFO queue (std::deque with pop_front ensures fairness)
 * 2. Identical workers (no priority levels, all pop from same queue)
 * 3. Condition variables notify all waiting threads on state changes
 * 4. Bounded queue prevents producer from overwhelming consumers
 * 
 * ==========================================================================================
 * BUILD
 * ==========================================================================================
 * Direct:  g++ -std=c++20 -O2 -pthread -o lfg src/main.cpp src/party_queue.cpp ...
 * Make:    make
 * CMake:   mkdir build && cd build && cmake .. && make
 * 
 * ==========================================================================================
 * USAGE
 * ==========================================================================================
 * Interactive: ./lfg
 * CLI:         ./lfg --instances 4 --tanks 10 --healers 10 --dps 30 --tmin 3 --tmax 8
 * Verbose:     ./lfg --instances 4 --tanks 10 --healers 10 --dps 30 --tmin 3 --tmax 8 --verbose
 * Bonus:       ./lfg --instances 4 --tanks 5 --healers 5 --dps 15 --tmin 2 --tmax 5 --dynamic-arrivals
 * 
 * ==========================================================================================
 * KEY FEATURES
 * ==========================================================================================
 * - Bounded queue with backpressure (producer blocks when full)
 * - Live status reporting (active/empty per instance)
 * - Final summary (parties served, total time per instance)
 * - Unmatched player tracking (leftover T/H/D)
 * - Deterministic mode (--seed for reproducible runs)
 * - Dynamic late arrivals (bonus feature with --dynamic-arrivals)
 */

