using namespace std;

const int STUDENT_COUNT = 20;

struct studentType
{
    string studentFName;
    string studentLName;
    int testScore;
    char grade;
};

void getData(studentType students[], int size);
void assignGrade(studentType students[], int size);
int highestScore(studentType students[], int size);
void printHighest(studentType students[], int size, int highScore);
void printAll(studentType students[], int size);

int main()
{
    studentType students[STUDENT_COUNT];

    getData(students, STUDENT_COUNT);
    assignGrade(students, STUDENT_COUNT);

    int highest = highestScore(students, STUDENT_COUNT);

    printAll(students, STUDENT_COUNT);
    cout << "\n\nStudents with highest test score:\n";
    printHighest(students, STUDENT_COUNT, highest);

    return 0;
}

void getData(studentType students[], int size)
{
    for (int i = 0; i < size; i++)
    {
        cout << "Enter first name, last name, and score for student " << i + 1 << ": ";
        cin >> students[i].studentFName >> students[i].studentLName >> students[i].testScore;
    }
}

void assignGrade(studentType students[], int size)
{
    for (int i = 0; i < size; i++)
    {
        int score = students[i].testScore;
        if (score >= 90)
            students[i].grade = 'A';
        else if (score >= 80)
            students[i].grade = 'B';
        else if (score >= 70)
            students[i].grade = 'C';
        else if (score >= 60)
            students[i].grade = 'D';
        else
            students[i].grade = 'F';
    }
}

int highestScore(studentType students[], int size)
{
    int maxScore = students[0].testScore;
    for (int i = 1; i < size; i++)
    {
        if (students[i].testScore > maxScore)
            maxScore = students[i].testScore;
    }
    return maxScore;
}

void printAll(studentType students[], int size)
{
    cout << left << setw(20) << "Name" << setw(10) << "Score" << "Grade\n";
    cout << "-------------------------------------\n";

    for (int i = 0; i < size; i++)
    {
        string fullName = students[i].studentLName + ", " + students[i].studentFName;
        cout << left << setw(20) << fullName
             << setw(10) << students[i].testScore
             << students[i].grade << endl;
    }
}

void printHighest(studentType students[], int size, int highScore)
{
    for (int i = 0; i < size; i++)
    {
        if (students[i].testScore == highScore)
        {
            cout << students[i].studentLName << ", " << students[i].studentFName
                 << " --> " << highScore << endl;
        }
    }
}
#include <cstdio>
