#include "Fusion.h"

struct State { double z=0, v=0; };
double accel_profile(double t){
  if (t < 2.2) return 25.0 - 2.0*t;  
  if (t < 12.0) return -9.81 + 0.3;   
  return 0.0;                         
}
int main(){
  const double P0=101325.0, dt=0.005, simT=18.0; 
  std::mt19937 rng(42);
  std::normal_distribution<float> n_acc(0.0f,0.15f), n_baro(0.0f,1.0f);
  State s; double t=0; FusionKF kf; kf.R=1.0f;
  FILE* f=std::fopen("flight.csv","w");
  std::fprintf(f,"t_s,alt_baro_m,alt_fused_m,vel_fused_mps,accZ_mps2,press_Pa,temp_C\n");
  while(t<=simT){
    double a=accel_profile(t); s.v+=a*dt; s.z+=s.v*dt; if(s.z<0 && t>0.2){s.z=0; s.v=0;}
    float P = pressure_from_alt((float)s.z,(float)P0);
    float zbar = hypsometric_alt(P,(float)P0) + n_baro(rng);
    float az   = (float)a + n_acc(rng);
    kfPredict(kf,(float)dt,az);
    kfUpdate(kf,zbar);
    std::fprintf(f,"%.3f,%.4f,%.4f,%.4f,%.4f,%.2f,%.2f\n",t,zbar,kf.z,kf.v,az,P,20.0);
    t+=dt;
  }
  std::fclose(f);
  std::puts("Wrote flight.csv  (PC simulation)");
}
