void Sand::drawGrid(sf::RenderWindow& window) {
	for (int y = 0; y < WIDTH; y += CELL_SIZE) {
		sf::Vertex y_lines[] = {
			sf::Vertex(sf::Vector2f(y,0), sf::Color::Green),
			sf::Vertex(sf::Vector2f(y, HEIGHT), sf::Color::Green),
		};
		window.draw(y_lines, 2, sf::Lines);
	}

	for (int x = 0; x < HEIGHT; x += CELL_SIZE) {
		sf::Vertex x_lines[] = {
			sf::Vertex(sf::Vector2f(0,x), sf::Color::Green),
			sf::Vertex(sf::Vector2f(WIDTH,x), sf::Color::Green),
		};
		window.draw(x_lines, 2, sf::Lines);
	}
}

void Sand::drawSand(sf::RenderWindow& window) {
	sf::Clock clock;
	for (int y = 0; y < HEIGHT / CELL_SIZE; y++) {
		for (int x = 0; x < WIDTH / CELL_SIZE; x++) {
			if (sandData[y][x]) {
				float ratio = float(y) / (HEIGHT / CELL_SIZE); // 0 at top, 1 at bottom
				sf::Uint8 red = 255 * ratio;
				sf::Uint8 green = 200 * (1 - ratio);
				sf::Uint8 blue = 50 + 205 * sin(ratio * 3.14);

				sf::RectangleShape sand_rect(sf::Vector2f(CELL_SIZE,CELL_SIZE));
				sand_rect.setFillColor(sf::Color::Color(red, green, blue, 255));
				sand_rect.setPosition(sf::Vector2f(x * CELL_SIZE, y * CELL_SIZE));
				window.draw(sand_rect);
			}
		}
	}
}

void Sand::switchGeneration() {
	for (int y = HEIGHT / CELL_SIZE - 2; y >= 0; y-- ) {
		for (int x = 0; x < WIDTH / CELL_SIZE; x++) {
			if (!sandData[y][x]) continue;
			if (!sandData[y + 1][x]) {
				sandData[y + 1][x] = true;
				sandData[y][x] = false;
			}
			else {
				bool randomRightDirection = rand() % 2;
				if (x < WIDTH / CELL_SIZE - 1 && randomRightDirection && !sandData[y + 1][x + 1]) {
					sandData[y + 1][x + 1] = true;
					sandData[y][x] = false;
				}
				else if(x >= 1 && !sandData[y+1][x-1]) {
					sandData[y + 1][x - 1] = true;
					sandData[y][x] = false;
				}
			}

		}
	}
}

void Sand::reset() {
	for (auto& row : sandData) {
		std::fill(row.begin(), row.end(), false);
	}
}

void Sand::randomInit() {
	int ibrahim;
	for (int y = 0; y < HEIGHT / CELL_SIZE; y++) {
		for (int x = 0; x < WIDTH / CELL_SIZE; x++) {
			ibrahim = rand() % 2;
			sandData[y][x] = (ibrahim ? true : false); 
		}
	}
}
#include <iostream>
#include <string>
#include <map>

std::string input;
std::string command;
std::string argument;

class LED{
    private:
    std::string name;
    bool status;


    public:
    LED(std::string chosen_name){
        status = false;
        name = chosen_name;
    }

    std::string getName(){ return name; }

    void turn_on(){
        status = true;
        std::cout << name <<" is now ON" << "\n\n";
    }

    void turn_off(){
        status = false;
        std::cout << name <<" is now OFF" << "\n\n";
    }

    void display_status(){
        std::string current_status = (status == true) ? "ON" : "OFF";

        std::cout << name <<" status is " << current_status << "\n\n";
    }

};

void to_lower_case(std::string &command);
void help_command();

auto trim = [](std::string &s) {
    size_t start = s.find_first_not_of(" ");
    size_t end   = s.find_last_not_of(" ");
    if (start == std::string::npos) { s = ""; return; }
    s = s.substr(start, end - start + 1);
};

std::map<std::string, LED> leds;


int main(){
    std::cout << "Welcome to the Mini Commander!" << "\n";
    std::cout << "If you want to see all commands type 'help'" << "\n\n";

    while(true){
        std::cout << "Insert Command: ";
        getline(std::cin, input);
        trim(input);

        size_t spacePos = input.find(' ');

        if (spacePos == std::string::npos) {
            // NO space was found
            command = input;
            argument = "";
        } else {
            command = input.substr(0, spacePos);
            argument = input.substr(spacePos + 1);
            trim(argument);
        }

        to_lower_case(command);

        if(command == "add"){
            std::string name_led = argument;

            if (leds.count(name_led)) {
                std::cout << "LED '" << name_led << "' already exists.\n";
            } else {
                leds.emplace(name_led, LED(name_led));
                std::cout << "LED '" << name_led << "' created.\n";
            }

        } else if(command == "off" || command == "on" || command == "status"){
            std::string name_led = argument;

            auto it = leds.find(name_led);
            if (it == leds.end()) {
                std::cout << "No LED named '" << name_led << "'.\n";
            } else {
                LED &led = it->second;
                if (command == "on") led.turn_on();
                else if (command == "off") led.turn_off();
                else if (command == "status") led.display_status();
            }

        }else if(command == "help"){
            help_command();

        } else if(command == "exit"){
            std::cout << "Goodbye, until next time!" << "\n\n";
            break;

         }else {
            std::cout << "'" << command << "' is a invalid command, Please type a valid command!" << "\n\n";
        }

    }

    return 0;
}


void to_lower_case(std::string &command){
    for(int i = 0; i < command.length(); i++){
        if(command[i] >= 'A' && command[i] <= 'Z'){
            command[i] = command[i] + ('a' - 'A');
        }
    }
}

void help_command(){
    std::cout << "All commands: add <name>, on <name>, off <name>, status <name>, help, exit" << "\n\n";
}
