    {
    }

    const std::string& String::getStdString() const
    {
        try
        {
            return spImpl->mString;
        }
        catch (const std::exception& e)
        {
            error(e.what(), __LINE__, __FUNCTION__, __FILE__);
            return spImpl->mString;
        }
    }

    bool String::empty() const
    {
        try
        {
            return spImpl->mString.empty();
        }
        catch (const std::exception& e)
        {
            error(e.what(), __LINE__, __FUNCTION__, __FILE__);
            return true;
        }
    }
}
