template<typename T>
class Stack {
public:
    struct StackOverflow : std::runtime_error { StackOverflow() : std::runtime_error("StackOverflow") {} };
    struct StackUnderflow : std::runtime_error { StackUnderflow() : std::runtime_error("StackUnderflow") {} };

    explicit Stack(std::size_t cap = 16) : capacity_(cap), top_(0), data_(cap ? std::make_unique<T[]>(cap) : nullptr) {}

    template<typename InputIt>
    Stack(InputIt first, InputIt last) {
        std::size_t n = static_cast<std::size_t>(std::distance(first, last));
        capacity_ = n;
        top_ = 0;
        data_ = capacity_ ? std::make_unique<T[]>(capacity_) : nullptr;
        for (auto it = first; it != last; ++it) data_[top_++] = *it;
    }

    Stack(const Stack&) = delete;
    Stack& operator=(const Stack&) = delete;

    Stack(Stack&& other) noexcept
        : capacity_(other.capacity_), top_(other.top_), data_(std::move(other.data_)) {
        other.capacity_ = 0;
        other.top_ = 0;
    }

    Stack& operator=(Stack&& other) noexcept {
        if (this != &other) {
            capacity_ = other.capacity_;
            top_ = other.top_;
            data_ = std::move(other.data_);
            other.capacity_ = 0;
            other.top_ = 0;
        }
        return *this;
    }

    void push(const T& value) {
        if (top_ >= capacity_) throw StackOverflow();
        data_[top_++] = value;
    }

    T pop() {
        if (top_ == 0) throw StackUnderflow();
        return data_[--top_];
    }

    const T& peek() const {
        if (top_ == 0) throw StackUnderflow();
        return data_[top_ - 1];
    }

    bool empty() const { return top_ == 0; }
    std::size_t size() const { return top_; }
    std::size_t capacity() const { return capacity_; }

private:
    std::size_t capacity_;
    std::size_t top_;
    std::unique_ptr<T[]> data_;
};

struct Big {
    Big() : id(++count) {}
    Big(const Big&) { id = ++count; }
    ~Big() {}
    int id;
    static int count;
};
int Big::count = 0;

int main() {
    Stack<int> s(10000);
    for (int i = 0; i < 10000; ++i) s.push(i);
    std::cout << "size after pushes: " << s.size() << "\n";
    for (int i = 0; i < 10; ++i) std::cout << s.pop() << " ";
    std::cout << "\nsize after pops: " << s.size() << "\n";

    std::vector<std::string> vs = {"one","two","three","four"};
    Stack<std::string> ss(vs.begin(), vs.end());
    while (!ss.empty()) {
        std::cout << ss.pop() << " ";
    }
    std::cout << "\n";

    std::vector<Big> vb;
    vb.resize(50000);
    Stack<Big> sb(vb.begin(), vb.end());
    std::cout << "Big objects in stack: " << sb.size() << "\n";
    while (!sb.empty()) sb.pop();
    std::cout << "Big stack emptied\n";

    return 0;
}
#include "../include/BlockScope/TransactionFetcher.h"
#include <iostream>

TransactionFetcher::TransactionFetcher(RpcClient& rpc_client,
                                        int max_batches,
                                        int max_txs,
                                        int limit_per_batch)
        : m_rpcClient(rpc_client),
          m_limit_per_batch(limit_per_batch),
          m_max_batches(max_batches),
          m_max_txs(max_txs) {}

std::vector<TransactionInfo> TransactionFetcher::fetchTransactions(const std::string& wallet) {
    std::vector<TransactionInfo> transactions;
    std::string beforeSig;
    int batchCount = 0;

    while (true) {
        if (batchCount >= m_max_batches || transactions.size() >= m_max_txs) {
            std::cout << "⚠️ Limit: " << transactions.size() << " tx, " << batchCount << " batches.\n";
            break;
        }

        nlohmann::json opts = {
            {"limit", m_limit_per_batch},
            {"commitment", "finalized"}
        };
        if (!beforeSig.empty()) {
            opts["before"] = beforeSig;
        }
        nlohmann::json params = {wallet, opts};

        auto result = m_rpcClient.call("getSignaturesForAddress", params);
        if (!result.contains("result") || result["result"].empty()) break;

        for (const auto& tx : result["result"]) {
            TransactionInfo info;
            info.signature = tx.value("signature", "");
            info.slot = tx.value("slot", 0LL);
            info.blockTime = tx.value("blockTime", 0LL);
            info.err = tx["err"].is_null() ? "ok" : "error";
            transactions.push_back(info);
        }

        beforeSig = result["result"][0]["signature"].get<std::string>();  // ← Фикс: [0] newest!
        batchCount++;
        std::cout << "* Batch " << batchCount << ", total: " << transactions.size() << "\n";

        if (result["result"].size() < static_cast<size_t>(m_limit_per_batch)) break;
    }
    return transactions;
}
