            u8g2.setCursor(0, yOffset);
            u8g2.print(line.c_str());
            yOffset += 10;  // Move to next line
            if (yOffset >= 64) break;  // Prevent overflow
        }
    }

    u8g2.display();  // Force OLED update
    Serial.println("OLED Updated!");
