        char c;
        for (;;)
        {
            read(m_port, buffer(&c, 1));
            if (c == '>') break; // ELM prompt
            response += c;
        }
        // strip CR/LF
        response.erase(remove(response.begin(), response.end(), '\r'), response.end());
        response.erase(remove(response.begin(), response.end(), '\n'), response.end());
        return response;
    }
}
