 * 
 * Working with time data, using the tm structure.
 * 
 */
#include <iostream>
#include <ctime>
#include <stdio.h>
using namespace std;
int main()
{
  // Number of seconds ellapsed since 00:00, Jan 1 1970 UTC
  time_t t = time(nullptr); 
  cout << "Current date and time as time_t: " << t << endl;
  // ctime returns a pointer to a character array containing the time information in the form weekday month date hours:minutes:seconds year
  cout << "Current date and time with ctime:\n" << ctime(&t) << endl;
  tm* localt;
  // localtime(&time): Converts the time given in time_t format into a tm structure, and returns pointer to the tm structure representing local time (it does not change the time value provided by ctime)
  localt = localtime(&t);
  cout << "Current date and time with tm structure: \n";
  cout.width(2);
  cout.fill('0');
  cout << localt->tm_hour << ":";
  cout.width(2);
  cout.fill('0');
  cout << localt->tm_min << ":";
  cout.width(2);
  cout.fill('0');
  cout << localt->tm_sec << ", ";
  string months[] = { "January","February",
    "March","April","May","June",
    "July","August","September",
    "October","November","December"
  };
  cout << months[localt->tm_mon] << " ";
  cout.width(2);
  cout.fill('0');
  cout << localt->tm_mday << ", ";
  cout << 1900 + localt->tm_year
    << endl << endl;
  // gmtime converts the time given in time_t format into Coordinated Universal Time (UTC, which is identical with GMT) stored in a tm structure. The function returns a pointer to the structure. UTC/GMT is one hour behind the Hungarian winter time (CET) and two hours behind the Hungarian summer time (CEST)
  tm* gmtt = gmtime(&t);
  // asctime(time): Converts a time object of type tm into a character array and returns a pointer to the array
  cout << "The current UTC date and time is:\n" << asctime(gmtt) << endl;

  double d = DBL_MAX;
  // clock(): Returns an approximate value for the amount of time the calling program has been running using  special clock_t unit. To get seconds it has to be divided by the CLOCKS_PER_SEC constant like macro
  // Let's measure the time ellapsed during the execusion of a loop with complex operations
  clock_t start = clock();
  int i = 0;
  do
  {
    d = pow(sqrt(pow(sqrt(pow(sqrt(d), 2)), 2)), 2) * 0.9999;
    i++;
  } while (d > 1);
  clock_t end = clock();
  double cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC;
  cout << "Number of square root operations: " << i << endl;
  cout << "Ellapsed time: " << cpu_time_used << " sec" << endl;
  return 0;
}


#include <opencv2/opencv.hpp>
#include <stdio.h>

#define IN_VIDEO_FILE "sample_video_input.avi"
#define OUT_VIDEO_FILE "sample_video_output.avi"

#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define FRAME_RATE 30

int main(int argc, char *argv[]){
    // 1. prepare VideoCapture Object
    cv::VideoCapture cap;
    std::string input_index;
    if(argc > 1){ // capture from video file
        input_index = argv[1];
        cap.open(input_index);
    }else{ // capture from camera
        cap.open(0);
    }

    // 2. prepare VideoWriter Object
    cv::Mat frame, copy_frame;
    int rec_mode= 0;

    cv::namedWindow("video", 1);
    cv::VideoWriter output_video;
    cap.set(cv::CAP_PROP_FPS, FRAME_RATE);
    cap.set(cv::CAP_PROP_FRAME_WIDTH, FRAME_WIDTH);
    cap.set(cv::CAP_PROP_FRAME_HEIGHT, FRAME_HEIGHT);

    output_video.open(
        OUT_VIDEO_FILE,
        cv::VideoWriter::fourcc('M','J','P','G'),
        FRAME_RATE,
        cv::Size(FRAME_WIDTH, FRAME_HEIGHT)
    ); // using "MJPG" as codec

    if(!cap.isOpened() || !output_video.isOpened()){
        printf("no input video\n");
        return 0;
    }
    else
    {
        bool loop_flag = true;
        while(loop_flag){

            // 3. capture frame from VideoCapture
            cap >> frame;
            if(frame.empty()){
                break;
            }

            // 4. save frame
            if(rec_mode){
                output_video << frame;
                frame.copyTo(copy_frame);
                cv::Size s = frame.size();
                cv::rectangle(copy_frame, cv::Point(0,0),
                              cv::Point(s.width-1, s.height-1),
                              cv::Scalar(0,0,255), 4, 8, 0);
                cv::imshow("video", copy_frame);
            }
            else{
                cv::imshow("video", frame);
            }

            // 5. process according to input key
            int k = cv::waitKey(33);
            switch(k){
                case 'q':
                case 'Q':
                    loop_flag = false;
                    break;

                case 'r':
                    if(rec_mode == 0){
                        rec_mode = 1;
                    }else{
                        rec_mode = 0;
                    }
                    break;
            }
        }
    }
    return 0;
}
