// Helper function to convert BF16 to float32
float bf16_to_float(uint16_t bf16) {
	uint32_t f32 = ((uint32_t)bf16) << 16;
	return *reinterpret_cast<float*>(&f32);
}

// Structure to hold layer weights efficiently
