// Helper function to load BF16 tensor and convert to float32
std::vector<float> load_bf16_tensor(std::ifstream& file, const TensorInfo& info, uint64_t base_offset) {
	size_t num_elements = 1;
	for (auto dim : info.shape) {
		num_elements *= dim;
	}

	// Seek to tensor data location
	file.seekg(base_offset + info.data_offset_begin);

	// Read BF16 data
	std::vector<uint16_t> bf16_data(num_elements);
	file.read(reinterpret_cast<char*>(bf16_data.data()), num_elements * sizeof(uint16_t));

	// Convert to float32
	std::vector<float> float_data(num_elements);
	for (size_t i = 0; i < num_elements; i++) {
		float_data[i] = bf16_to_float(bf16_data[i]);
	}

	return float_data;
}

// Helper function to load U8 tensor (for MXFP4 weights)
std::vector<uint8_t> load_u8_tensor(std::ifstream& file, const TensorInfo& info, uint64_t base_offset) {
	size_t num_elements = 1;
	for (auto dim : info.shape) {
		num_elements *= dim;
	}

	// Seek to tensor data location
	file.seekg(base_offset + info.data_offset_begin);

	// Read U8 data
	std::vector<uint8_t> data(num_elements);
	file.read(reinterpret_cast<char*>(data.data()), num_elements);

	return data;
}

