/**
 * @file party_queue.cpp
 * @brief Implementation of bounded blocking queue
 * 
 * Key synchronization patterns:
 * 1. Predicate-based wait loops prevent spurious wakeups
 * 2. Single lock per operation (no nested locks)
 * 3. Lock released automatically during cv.wait()
 * 4. Separate CVs for push/pop avoid unnecessary wakeups
 */

#include "party_queue.hpp"

namespace lfg {

PartyJobQueue::PartyJobQueue(size_t capacity)
    : cap_(capacity), closed_(false) {}

bool PartyJobQueue::push(const Party& job) {
    std::unique_lock<std::mutex> lk(mtx_);

    // Wait while queue is full (and not closed)
    // Predicate lambda prevents spurious wakeups from breaking logic
    cv_push_.wait(lk, [this] { return closed_ || q_.size() < cap_; });

    if (closed_) return false;  // Shutdown signal received

    q_.push_back(job);
    cv_pop_.notify_one();  // Wake exactly one waiting consumer
    return true;
}

bool PartyJobQueue::pop(Party& out) {
    std::unique_lock<std::mutex> lk(mtx_);

    // Wait while queue is empty (and not closed)
    // Predicate lambda prevents spurious wakeups
    cv_pop_.wait(lk, [this] { return closed_ || !q_.empty(); });

    // If closed and empty, signal consumer to exit
    if (q_.empty()) return false;  // Queue drained, shutdown complete

    out = std::move(q_.front());
    q_.pop_front();  // FIFO ordering
    cv_push_.notify_one();  // Wake one waiting producer (backpressure release)
    return true;
}

void PartyJobQueue::close() {
    std::unique_lock<std::mutex> lk(mtx_);
    closed_ = true;
    // Wake all threads so they can check closed flag and exit gracefully
    cv_push_.notify_all();
    cv_pop_.notify_all();
}

size_t PartyJobQueue::size() const {
    std::lock_guard<std::mutex> lk(mtx_);
    return q_.size();
}

} // namespace lfg
