json LMSRequestBuilder::extractMessagesArray(const json& message)
{
    json messages = json::array();

    // Handle your custom format: {"content": "...", "count": 0, "roomId": "...", "type": 0}
    if (message.contains("content") && !message.contains("role"))
    {
        json userMsg;
        userMsg["role"] = "user";
        userMsg["content"] = message["content"];
        messages.push_back(userMsg);
        return messages;
    }

    // If message already has a "messages" array, use it
    if (message.contains("messages") && message["messages"].is_array())
    {
        return message["messages"];
    }

    // If message is already an array, use it directly
    if (message.is_array())
    {
        return message;
    }

    // If message is a single message object with role and content
    if (message.contains("role") && message.contains("content"))
    {
        messages.push_back(message);
        return messages;
    }

    // If message is just a string, create a user message
    if (message.is_string())
    {
        json userMsg;
        userMsg["role"] = "user";
        userMsg["content"] = message.get<std::string>();
        messages.push_back(userMsg);
        return messages;
    }

    // If message has a "prompt" field, convert it
    if (message.contains("prompt"))
    {
        json userMsg;
        userMsg["role"] = "user";
        userMsg["content"] = message["prompt"];
        messages.push_back(userMsg);
        return messages;
    }

    // If message has "text" field
    if (message.contains("text"))
    {
        json userMsg;
        userMsg["role"] = "user";
        userMsg["content"] = message["text"];
        messages.push_back(userMsg);
        return messages;
    }

    throw std::invalid_argument("Invalid message format: missing 'content', 'messages', 'role', 'prompt', or 'text' field");
}

