{
    json request;

    // Required fields
    request["model"] = model_;

    try
    {
        request["messages"] = extractMessagesArray(message);
		request["rId"] = message.contains("roomId") ? message["roomId"] : nullptr;
		request["count"] = message.contains("count") ? message["count"] : nullptr;
    }
    catch (const std::exception& e)
    {
        // If extraction fails, provide more details
        throw std::invalid_argument(std::string("Failed to extract messages: ") + e.what() +
            ". Message content: " + message.dump());
    }

    // Optional parameters
    request["temperature"] = temperature;
    request["stream"] = false;

    if (maxTokens > 0)
    {
        request["max_tokens"] = maxTokens;
    }

    // Add any additional parameters from the original message
    if (message.is_object())
    {
        // Copy over other parameters if they exist
        if (message.contains("top_p"))
            request["top_p"] = message["top_p"];

        if (message.contains("frequency_penalty"))
            request["frequency_penalty"] = message["frequency_penalty"];

        if (message.contains("presence_penalty"))
            request["presence_penalty"] = message["presence_penalty"];

        if (message.contains("stop"))
            request["stop"] = message["stop"];
    }

    return request;
}

