#include "../../points/Point.h"
#include <cmath>
#include "geometry_functions.h"
/**
* @brief Oblicza iloczyn wektorowy dla trzech punktów.
 */
double cross_product(const Point& a, const Point& b, const Point& c)
{
    return (b.getX() - a.getX()) * (c.getY() - a.getY()) -
        (b.getY() - a.getY()) * (c.getX() - a.getX());
}

/**
* @brief Oblicza odległość euklidesową między dwoma punktami.
 */
double calculate_distance_between_two_points(const Point& a, const Point& b)
{
    return sqrt(pow(b.getX() - a.getX(), 2) + pow(b.getY() - a.getY(), 2));
}

/**
 * @brief Oblicza odległość punktu (c) od linii przechodzącej przez (a, b).
 */
double calculate_distance_between_line_and_point(const Point& a, const Point& b, const Point& c)
{
    double base = calculate_distance_between_two_points(a, b);
    // przypadek brzgowy gdy linia to pojedynczy punkt (a == b)
    if (base == 0)
    {
        return calculate_distance_between_two_points(a, c);
    }
    return abs(cross_product(a, b, c)) / base;
}
