        if (carInfo.find(InputCarName) != carInfo.end()) {
            cout << "\n-----------------------------------\n";
            cout << "Found Car: " << InputCarName << endl;
            cout << "Model: " << carInfo[InputCarName].Model << endl;
            cout << "Year: " << carInfo[InputCarName].Year << endl;
            cout << "Price: " << carInfo[InputCarName].Price << " $" << endl;
            cout << "-----------------------------------\n";
        } else {
            cout << "\n-----------------------------------\n";
            cout << "Car not found!\n";
            cout << "-----------------------------------\n";
        }
    }

