        string CarNameInput, ModelInput;
        int YearInput, PriceInput;

        cout << "\nEnter new car name: ";
        cin >> CarNameInput;
        cout << "Enter model: ";
        cin >> ModelInput;
        cout << "Enter year: ";
        cin >> YearInput;
        cout << "Enter price: ";
        cin >> PriceInput;

        carInfo[CarNameInput] = {ModelInput, YearInput, PriceInput};
        cout << "\n✅ Car added successfully!\n";
    }

    void ShowAllCars() {
        cout << "\n===== Current Car List =====\n";
        for (auto& car : carInfo) {
            cout << car.first << " - " << car.second.Model 
                 << " (" << car.second.Year << ") | Price: " 
                 << car.second.Price << "$" << "\n";
        }
        cout << "============================\n";
    }

    void BuyCar() {
        string carName;
        int userMoney;

        cout << "\nEnter car name you want to buy: ";
        cin >> carName;
        cout << "Enter your budget ($): ";
        cin >> userMoney;

        if (carInfo.find(carName) != carInfo.end()) {
            int price = carInfo[carName].Price;

            cout << "\nCar price: " << price << "$" << endl;

            if (userMoney >= price) {
                cout << "Congratulations! You bought the " << carName << "!\n";
                carInfo.erase(carName);
            } else {
                cout << "Sorry, you don't have enough money.\n";
            }
        } else {
            cout << "\nCar not found!\n";
        }
    }
};

