QString colorToCss(const QColor &color)
{
    if (color.alpha() == 255) {
        return color.name();
    }
    return QString("rgba(%1,%2,%3,%4)")
        .arg(color.red())
        .arg(color.green())
        .arg(color.blue())
        .arg(QString::number(color.alphaF(), 'f', 2));
}
}

