    Uint64 result = 0;  // Single exit point variable

    if (k > n) {
        result = 0;
    } else if (k == 0 || k == n) {
        result = 1;
    } else if (k == 1) {
        result = n;
    } else {
        // Optimize: C(n,k) = C(n, n-k), use smaller k
        if (k > n - k) {
            k = n - k;
        }

        // Iterative calculation to avoid overflow
        result = 1;
        for (Uint32 i = 1; i <= k; ++i) {
            result = result * (n - k + i) / i;
        }
    }

    return result;  // Single exit point
}

