    // remove
    int ans = 1 + get(i + 1, j, word, forbid, dp, forbidden);

    //add
    int f = forbid[word[i]];
    if(f == (word[i] - 'a')){
        ans = min(ans, get(i + 1, f, word, forbid, dp, forbidden));
    } else {

        // check only if last != f

        if(j == f){
