bool UDetectSharpEdges::DetectSharpEdges(const std::shared_ptr<Mesh> &pMesh, QVector<Segment> &vecSegments)
{
    typedef boost::property_map<Mesh, CGAL::edge_is_feature_t>::type EIFMap;
    typedef boost::property_map<Mesh, CGAL::face_patch_id_t<int>>::type PIMap;
    typedef boost::property_map<Mesh, CGAL::vertex_incident_patches_t<int>>::type VIMap;

    EIFMap eif = CGAL::get(CGAL::edge_is_feature, *pMesh);
    PIMap pid = CGAL::get(CGAL::face_patch_id_t<int>(), *pMesh);
    VIMap vip = CGAL::get(CGAL::vertex_incident_patches_t<int>(), *pMesh);

    std::size_t number_of_patches
        = PMP::sharp_edges_segmentation(*pMesh, 30.0, eif, pid,
                                        CGAL::parameters::vertex_incident_patches_map(vip));
    qInfo() << "DetectSharpEdges" << pMesh->faces().size() << number_of_patches;

    for(const boost::graph_traits<Mesh>::edge_descriptor &e : CGAL::edges(*pMesh)) {
        if(boost::get(eif, e)) {
            auto v1 = source(e, *pMesh);
            auto v2 = target(e, *pMesh);
            vecSegments.append(Segment(Point(pMesh->point(v1).x(), pMesh->point(v1).y(), pMesh->point(v1).z()),
                                    Point(pMesh->point(v2).x(), pMesh->point(v2).y(), pMesh->point(v2).z())));
        }
    }

    return true;
}
