#include <iostream>
#include <vector>
#include <iomanip>
#include <cstdlib>
using namespace std;

int comparisons = 0, swaps = 0;

void printArray(const vector<int>& arr) {
    for (int x : arr) cout << setw(3) << x << " ";
    cout << endl;
}

// ------------------ Bubble Sort ------------------
void bubbleSort(vector<int>& arr) {
    int n = arr.size();
    cout << "\n=== Bubble Sort ===\n";
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            comparisons++;
            cout << "Compare index " << j << " & " << j + 1 << ": "
                 << arr[j] << " vs " << arr[j + 1];
            if (arr[j] > arr[j + 1]) {
                cout << " -> swap\n";
                swap(arr[j], arr[j + 1]);
                swaps++;
            } else {
                cout << " -> no swap\n";
            }
            printArray(arr);
        }
    }
}

// ------------------ Selection Sort ------------------
void selectionSort(vector<int>& arr) {
    int n = arr.size();
    cout << "\n=== Selection Sort ===\n";
    for (int i = 0; i < n - 1; i++) {
        int minIdx = i;
        for (int j = i + 1; j < n; j++) {
            comparisons++;
            cout << "Compare index " << minIdx << " & " << j << ": "
                 << arr[minIdx] << " vs " << arr[j] << endl;
            if (arr[j] < arr[minIdx])
                minIdx = j;
        }
        if (minIdx != i) {
            swap(arr[i], arr[minIdx]);
            swaps++;
            cout << "Swap index " << i << " & " << minIdx << endl;
        }
        printArray(arr);
    }
}

// ------------------ Quick Sort ------------------
int partition(vector<int>& arr, int low, int high) {
    int pivot = arr[high];
    cout << "\nPartition call: low=" << low << ", high=" << high
         << ", pivot=" << pivot << " (index " << high << ")\n";

    int i = low - 1;
    for (int j = low; j < high; j++) {
        comparisons++;
        cout << "Step: compare index " << j << " & pivotIndex " << high
             << " -> " << arr[j] << " ? " << pivot;
        if (arr[j] < pivot) {
            i++;
            swap(arr[i], arr[j]);
            swaps++;
            cout << " -> swap\n";
        } else {
            cout << " -> no swap\n";
        }
        printArray(arr);
    }
    swap(arr[i + 1], arr[high]);
    swaps++;
    cout << "Move pivot to index " << i + 1 << endl;
    printArray(arr);
    return i + 1;
}

void quickSort(vector<int>& arr, int low, int high) {
    if (low < high) {
        cout << "QuickSort call: low=" << low << ", high=" << high << " (enter)\n";
        int pi = partition(arr, low, high);
        cout << "Partition result: pivotIndex = " << pi << endl;
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
        cout << "QuickSort call: low=" << low << ", high=" << high << " (exit)\n";
    }
}

