int main() {
    vector<int> arr = {10, 3, 15, 7, 8, 23, 74};
    vector<int> arrCopy;

    cout << "Initial array:\n";
    printArray(arr);

    cout << "\nChoose Sorting Algorithm ya Eng Nermeen:\n";
    cout << "1. Bubble Sort\n2. Selection Sort\n3. Quick Sort\n> ";
    int choice;
    cin >> choice;

    comparisons = 0;
    swaps = 0;

    switch (choice) {
        case 1:
            arrCopy = arr;
            bubbleSort(arrCopy);
            break;
        case 2:
            arrCopy = arr;
            selectionSort(arrCopy);
            break;
        case 3:
            arrCopy = arr;
            cout << "\n=== Quick Sort (Lomuto) ===\n";
            quickSort(arrCopy, 0, arrCopy.size() - 1);
            break;
        default:
            cout << "Invalid choice\n";
            return 0;
    }

    cout << "\nFinal sorted array:\n";
    printArray(arrCopy);
    cout << "\nTotal comparisons = " << comparisons
         << ", Total swaps = " << swaps << endl;

    return 0;
}
