namespace hemd
{
    PID::PID(double kp, double ki, double kd, int min, int max) : _kp(kp), _ki(ki), _kd(kd),
                                                                  _min(min), _max(max),
                                                                  _prev_error(0), _integral(0)
    {
    }

    int PID::calculate(double setpoint, double measurement)
    {
        setpoint = std::isnan(setpoint) ? 0 : setpoint;
        measurement = std::isnan(measurement) ? 0 : measurement;

        if (setpoint == 0.0)
        {
            _integral = 0;
            _prev_error = 0;

            return 0;
        }

        double error = setpoint - measurement;
        double derivative = error - _prev_error;

        _integral += error;
        _prev_error = error;

        int output = static_cast<int>(std::round(_kp * error + _ki * _integral + _kd * derivative));
        std::clamp(output, _min, _max);

        return output;
    }
} // hemd
