FaissIndex::FaissIndex() {}
FaissIndex::FaissIndex(size_t dim, size_t nlist, size_t m) : dim_(dim), nlist_(nlist), m_(m)
{
#ifdef HAVE_FAISS
    // Lazy allocate in train
#else
    (void)dim; (void)nlist; (void)m;
#endif
}

void FaissIndex::train(const std::vector<std::vector<float>>& data) {
#ifdef HAVE_FAISS
    if (dim_ == 0) throw std::runtime_error("FaissIndex not initialized");
    faiss::IndexFlatL2 quantizer(dim_);
    Impl* impl = new Impl();
    faiss::IndexIVFPQ* idx = new faiss::IndexIVFPQ(&quantizer, dim_, nlist_, m_, 8);
    idx->train(data.size(), reinterpret_cast<const float*>(data[0].data()));
    impl_ = reinterpret_cast<Impl*>(idx);
#else
    (void)data; throw std::runtime_error("FAISS not enabled. Rebuild with -DENABLE_FAISS=ON and provide FAISS") ;
#endif
}

void FaissIndex::add(const std::vector<std::vector<float>>& data) {
#ifdef HAVE_FAISS
    auto* idx = reinterpret_cast<faiss::IndexIVFPQ*>(impl_);
    const float* ptr = reinterpret_cast<const float*>(data[0].data());
    faiss::idx_t n = (faiss::idx_t)data.size();
    idx->add(n, ptr);
#else
    (void)data; throw std::runtime_error("FAISS not enabled.");
#endif
}

std::vector<std::pair<size_t, float>> FaissIndex::search(const std::vector<float>& query, size_t k, size_t nprobe) const {
#ifdef HAVE_FAISS
    auto* idx = reinterpret_cast<faiss::IndexIVFPQ*>(impl_);
    idx->nprobe = static_cast<int>(nprobe);
    std::vector<faiss::idx_t> I(k);
    std::vector<float> D(k);
    idx->search(1, query.data(), k, D.data(), I.data());
    std::vector<std::pair<size_t,float>> out;
    out.reserve(k);
    for (size_t i = 0; i < k; ++i) out.emplace_back(static_cast<size_t>(I[i]), D[i]);
    return out;
#else
    (void)query; (void)k; (void)nprobe; throw std::runtime_error("FAISS not enabled.");
#endif
}

void FaissIndex::save(const std::string& prefix) const {
#ifdef HAVE_FAISS
    auto* idx = reinterpret_cast<const faiss::IndexIVFPQ*>(impl_);
    std::string path = prefix + ".faiss";
    faiss::write_index(idx, path.c_str());
#else
    (void)prefix; throw std::runtime_error("FAISS not enabled.");
#endif
}

void FaissIndex::load(const std::string& prefix) {
#ifdef HAVE_FAISS
    std::string path = prefix + ".faiss";
    auto* idx = dynamic_cast<faiss::IndexIVFPQ*>(faiss::read_index(path.c_str()));
    if (!idx) throw std::runtime_error("Failed to load FAISS index");
    impl_ = reinterpret_cast<Impl*>(idx);
    dim_ = idx->d; // update
#else
    (void)prefix; throw std::runtime_error("FAISS not enabled.");
#endif
}

