    std::vector<int> tokens = tokenizer.encode(text);

    // For demonstration, set the target as "next token"
    std::vector<int> target(tokens.size());
    for (size_t i = 0; i < tokens.size(); i++)
        target[i] = (tokens[i] + 1) % vocab;

