#include <iostream>
using namespace std;

// ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
// Node Class
// ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

class Node
{
    int data;   // candy
    Node *next; // next house
    Node();
    Node(int);
    Node(int item, Node *n);
    friend class LL;
};

Node::Node() : next(nullptr) {}
Node::Node(int item) : data(item), next(nullptr) {}
Node::Node(int item, Node *n) : data(item), next(n) {}

// ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
// Linked List Class (Scavenger Hunt)
// ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
class LL
{
    Node *head;

public:
    LL();
    void Insert(int item);
    void InsertEnd(int item);
    void Print() const;
};

// LL
LL::LL() : head(nullptr) {}

// Insert
void LL::Insert(int item)
{
    // Insert at the head of the list
    head = new Node(item, head);
}

// InsertEnd
void LL::InsertEnd(int item)
{
    if (head == nullptr)
    {
        head = new Node(item);
    }
    else
    {
        Node *temp = head;
        while (temp->next != nullptr)
        {
            temp = temp->next;
        }
        temp->next = new Node(item);
    }
}

// Print
void LL::Print() const
{
    // start at the beginning
    Node *temp = head;
    // while not at the end
    while (temp != nullptr)
    {
        // print current
        cout << (*temp).data << endl;
        // go to next house
        temp = (*temp).next;
    }
}

// ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

int main()
{
    LL l;

    // InsertEnd 20
    l.InsertEnd(20);
    l.Print();
    cout << endl;

    // InsertEnd 40
    l.InsertEnd(40);
    l.Print();
    cout << endl;

    // InsertEnd 60
    l.InsertEnd(60);
    l.Print();
    cout << endl;

    return 0;
}
#include "slam/graph_optimizer_gtsam.hpp"
#include <gtsam/nonlinear/ISAM2.h>
#include <gtsam/nonlinear/NonlinearFactorGraph.h>
#include <gtsam/nonlinear/Values.h>
#include <gtsam/geometry/Pose3.h>
#include <gtsam/slam/BetweenFactor.h>
#include <gtsam/slam/PriorFactor.h>
#include <gtsam/inference/Symbol.h>
using gtsam::Symbol;
namespace slam {
static gtsam::Pose3 IsoToPose3(const Eigen::Isometry3d& T) {
  return gtsam::Pose3(gtsam::Rot3(T.rotation()), gtsam::Point3(T.translation()));
}
static Eigen::Isometry3d Pose3ToIso(const gtsam::Pose3& P) {
  Eigen::Isometry3d T = Eigen::Isometry3d::Identity();
  T.linear() = P.rotation().matrix(); T.translation() = P.translation().vector(); return T;
}
struct GraphOptimizerGTSAM::Impl {
  gtsam::ISAM2 isam; gtsam::NonlinearFactorGraph graph; gtsam::Values initial; bool has_prior = false;
  Impl() : isam(gtsam::ISAM2Params()) {}
};
GraphOptimizerGTSAM::GraphOptimizerGTSAM() : impl_(new Impl) {}
int GraphOptimizerGTSAM::addNode(const Eigen::Isometry3d &T_wb) {
  int id = static_cast<int>(nodes_.size()); nodes_.push_back({id, T_wb});
  gtsam::Key k = Symbol('x', id); impl_->initial.insert(k, IsoToPose3(T_wb));
  if (!impl_->has_prior && id == 0) { auto noise = gtsam::noiseModel::Constrained::All(6);
    impl_->graph.add(gtsam::PriorFactor<gtsam::Pose3>(k, IsoToPose3(T_wb), noise)); impl_->has_prior = true; }
  return id;
}
void GraphOptimizerGTSAM::addOdometryEdge(int i, int j, const Eigen::Isometry3d &T_ij, const Eigen::Matrix<double,6,6> &info) {
  auto noise = gtsam::noiseModel::Gaussian::Information(info);
  impl_->graph.add(gtsam::BetweenFactor<gtsam::Pose3>(Symbol('x', i), Symbol('x', j), IsoToPose3(T_ij), noise));
}
void GraphOptimizerGTSAM::addLoopEdge(int i, int j, const Eigen::Isometry3d &T_ij, const Eigen::Matrix<double,6,6> &info) {
  addOdometryEdge(i, j, T_ij, info);
}
void GraphOptimizerGTSAM::optimize(int iterations) {
  impl_->isam.update(impl_->graph, impl_->initial);
  for (int k = 1; k < iterations; ++k) impl_->isam.update();
  impl_->graph.resize(0); impl_->initial.clear();
  gtsam::Values result = impl_->isam.calculateEstimate();
  for (auto &n : nodes_) n.T_wb = Pose3ToIso(result.at<gtsam::Pose3>(Symbol('x', n.id)));
}
