    {
        forward();
    }

    // 右侧检测到黑线，左侧未检测到，右转
    else if (rightGray < 400 && leftGray > 400 && lineFlag == 0)
    {
        turnRight();
    }

    // 左侧检测到黑线，右侧未检测到，左转
    else if (rightGray > 400 && leftGray < 400 && lineFlag == 0)
    {
        turnLeft();
    }

    else if (rightGray < 400 && leftGray > 400 && lineFlag != 0)
    {
        turnRightPower();
    }

    else if (rightGray > 400 && leftGray < 400 && lineFlag != 0)
    {
        turnLeftPower();
    }

    // 两侧均检测到黑线，更新状态标志
    else
    {
        lineFlag++;
    }
