#include <bits/stdc++.h>
using namespace std;

int mod = 1e9 + 7;
int base = 31;

vector<int> pows;
vector<int> pref_hash;

void compute_pows(int base, int n)
{
    pows.resize(n);
    pows[0] = 1;
    for (int i = 1; i < n; i++)
    {
        pows[i] = (1LL * pows[i - 1] * base) % mod;
    }
}

void compute_pref_hash(const string &s)
{
    int n = s.size();
    pref_hash.resize(n);
    pref_hash[0] = (s[0] - 'a' + 1);
    for (int i = 1; i < n; i++)
    {
        pref_hash[i] = (pref_hash[i - 1] + 1LL * (s[i] - 'a' + 1) * pows[i]) % mod;
    }
}

bool check(const string &s, const string &pattern)
{
    int n = s.size();
    int m = pattern.size();
    if (m > n)
        return false;

    int pattern_hash = 0;
    for (int i = 0; i < m; i++)
    {
        pattern_hash = (pattern_hash + 1LL * (pattern[i] - 'a' + 1) * pows[i]) % mod;
    }

    // pattern ending at index i of s
    for(int i = m - 1; i < n; i++)
    {
        int curr_hash = pref_hash[i];
        if (i - m >= 0)
        {
            curr_hash = (curr_hash - pref_hash[i - m] + mod) % mod;
        }

        if (curr_hash == (1LL * pattern_hash * pows[i - m + 1]) % mod)
        {
            return true;
        }
    }
    return false;
}

int main()
{
    ios::sync_with_stdio(false);
    string s;
    cin >> s;
    string pattern;
    cin >> pattern;
    compute_pows(base, s.size());
    compute_pref_hash(s);
    if (check(s, pattern))
    {
        cout << "Pattern found in the string.\n";
    }
    else
    {
        cout << "Pattern not found in the string.\n";
    }

    return 0;
}
